  1	// src/lib/plattform/backend/demo/speicher.js
  2	//
  3	// Datei-Datenbank des Demo-Backends: eine JSON-Datei unter .data/plattform.json
  4	// (steht in .gitignore). Schreiben nur unter einer Sperrdatei (funktioniert auch,
  5	// wenn Next.js das Modul mehrfach lädt) und atomar über Datei + Umbenennen.
  6	// Uploads liegen unter .data/uploads/ mit zufälligen Dateinamen.
  7	
  8	import { promises as fs, readFileSync, statSync } from "node:fs";
  9	import path from "node:path";
 10	import { AsyncLocalStorage } from "node:async_hooks";
 11	
 12	export const DATEN_ORDNER = path.join(process.cwd(), ".data");
 13	export const UPLOAD_ORDNER = path.join(DATEN_ORDNER, "uploads");
 14	const DATEI = path.join(DATEN_ORDNER, "plattform.json");
 15	const SPERRE = path.join(DATEN_ORDNER, "plattform.lock");
 16	const SCHEMA = 2; // 2: Benachrichtigungen, Postausgang, Aufgaben, Checklisten
 17	
 18	let cache = null; // { mtimeMs, size, db }
 19	
 20	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
 21	
 22	// Sperrdatei: schützt gegen parallele Schreiber aus mehreren Prozessen.
 23	// Unter Last (viele parallele Tests) darf sie NIE einem lebenden Prozess
 24	// weggenommen werden – sonst gehen Schreibvorgänge verloren. Verwaist ist eine
 25	// Sperre nur, wenn der eingetragene Prozess nicht mehr existiert oder sie sehr
 26	// alt ist (Absturz mitten im Schreiben).
 27	function prozessLebt(pid) {
 28	  if (!pid) return false;
 29	  try {
 30	    process.kill(pid, 0);
 31	    return true;
 32	  } catch (e) {
 33	    return e.code === "EPERM";
 34	  }
 35	}
 36	
 37	async function sperren() {
 38	  await fs.mkdir(DATEN_ORDNER, { recursive: true });
 39	  const start = Date.now();
 40	  for (;;) {
 41	    try {
 42	      const h = await fs.open(SPERRE, "wx");
 43	      await h.writeFile(String(process.pid));
 44	      await h.close();
 45	      return;
 46	    } catch (e) {
 47	      if (e.code !== "EEXIST") throw e;
 48	      try {
 49	        const st = await fs.stat(SPERRE);
 50	        const pid = Number(readFileSync(SPERRE, "utf8")) || 0;
 51	        const alt = Date.now() - st.mtimeMs;
 52	        if ((!prozessLebt(pid) && alt > 2000) || alt > 120000) await fs.rm(SPERRE, { force: true });
 53	      } catch {
 54	        /* inzwischen weg */
 55	      }
 56	      if (Date.now() - start > 60000) throw new Error("Demo-Datenbank ist gesperrt");
 57	      await warte(15 + Math.random() * 35);
 58	    }
 59	  }
 60	}
 61	
 62	async function entsperren() {
 63	  await fs.rm(SPERRE, { force: true }).catch(() => {});
 64	}
 65	
 66	// Innerhalb eines Prozesses: Schreibvorgänge strikt nacheinander (Warteschlange),
 67	// statt dass viele gleichzeitige Anfragen um die Sperrdatei konkurrieren.
 68	// Auf globalThis, damit mehrfach geladene Modulinstanzen dieselbe Schlange teilen.
 69	const SCHLANGE = Symbol.for("oekoinvest.demo.schreibschlange");
 70	const IM_SCHREIBEN = (globalThis[Symbol.for("oekoinvest.demo.imSchreiben")] ||= new AsyncLocalStorage());
 71	function nacheinander(fn) {
 72	  // Verschachtelter Schreibzugriff würde auf sich selbst warten (Deadlock) –
 73	  // und außerdem die äußere Änderung überschreiben. Deshalb klarer Fehler.
 74	  // Nur solange die äußere Änderung läuft; danach gestartete Folgeaufgaben (die den
 75	  // Kontext erben) dürfen normal schreiben.
 76	  if (IM_SCHREIBEN.getStore()?.aktiv) throw new Error("Verschachtelter Schreibzugriff auf die Demo-Datenbank (aendern in aendern)");
 77	  const vorher = globalThis[SCHLANGE] || Promise.resolve();
 78	  const lauf = vorher.catch(() => {}).then(() => {
 79	    const zustand = { aktiv: true };
 80	    return IM_SCHREIBEN.run(zustand, async () => {
 81	      try {
 82	        return await fn();
 83	      } finally {
 84	        zustand.aktiv = false;
 85	      }
 86	    });
 87	  });
 88	  globalThis[SCHLANGE] = lauf.catch(() => {});
 89	  return lauf;
 90	}
 91	
 92	// Wiederhergestellt (Team Service): dateiLesen, dateiSchreiben und seedFn fehlten seit Commit 640c032
 93	// (ReferenceError bei jedem Zugriff) – unverändert aus dem Stand davor übernommen.
 94	
 95	// BEWUSST SYNCHRON: React 19 schneidet im Dev-Modus den Rückgabewert von
 96	// awaited I/O (fs.promises) für die Debug-Anzeige mit und liefert ihn im
 97	// HTML aus – das war die komplette Demo-Datenbank inkl. Passwort-Hashes auf
 98	// jeder Seite (2–5 MB). Synchrones Lesen erzeugt keinen solchen I/O-Eintrag.
 99	async function dateiLesen() {
100	  try {
101	    const st = statSync(DATEI);
102	    if (cache && cache.mtimeMs === st.mtimeMs && cache.size === st.size) return structuredClone(cache.db);
103	    const roh = readFileSync(DATEI, "utf8");
104	    const db = JSON.parse(roh);
105	    cache = { mtimeMs: st.mtimeMs, size: st.size, db };
106	    return structuredClone(db);
107	  } catch (e) {
108	    if (e.code === "ENOENT") return null;
109	    throw e;
110	  }
111	}
112	
113	async function dateiSchreiben(db) {
114	  const tmp = `${DATEI}.${process.pid}.${Date.now()}.tmp`;
115	  await fs.writeFile(tmp, JSON.stringify(db, null, 1), "utf8");
116	  for (let i = 0; ; i++) {
117	    try {
118	      await fs.rename(tmp, DATEI);
119	      break;
120	    } catch (e) {
121	      // Windows: Ziel kurzzeitig von einem Leser geöffnet
122	      if (i > 20 || !["EPERM", "EBUSY", "EACCES"].includes(e.code)) {
123	        await fs.rm(tmp, { force: true }).catch(() => {});
124	        throw e;
125	      }
126	      await warte(15);
127	    }
128	  }
129	  cache = null;
130	}
131	
132	let seedFn = null;
133	/** Seed-Funktion registrieren (liefert eine neue, befüllte Datenbank) */
134	export function seedSetzen(fn) {
135	  seedFn = fn;
136	}
137	
138	async function sicherstellen() {
139	  const db = await dateiLesen();
140	  if (db && db.schema === SCHEMA) return db;
141	  await sperren();
142	  try {
143	    const erneut = await dateiLesen();
144	    if (erneut && erneut.schema === SCHEMA) return erneut;
145	    const neu = await seedFn();
146	    neu.schema = SCHEMA;
147	    await dateiSchreiben(neu);
148	    return structuredClone(neu);
149	  } finally {
150	    await entsperren();
151	  }
152	}
153	
154	/** Nur lesen (Kopie – Änderungen daran werden NICHT gespeichert) */
155	export async function lesen() {
156	  return sicherstellen();
157	}
158	
159	/** Lesen, ändern, speichern unter Sperre. `fn(db)` darf db verändern und ein Ergebnis liefern. */
160	export async function aendern(fn) {
161	  await sicherstellen();
162	  return nacheinander(async () => {
163	    await sperren();
164	    try {
165	      const db = await dateiLesen();
166	      const ergebnis = await fn(db);
167	      await dateiSchreiben(db);
168	      return ergebnis;
169	    } finally {
170	      await entsperren();
171	    }
172	  });
173	}
174	
175	export async function uploadSchreiben(dateiname, daten) {
176	  await fs.mkdir(UPLOAD_ORDNER, { recursive: true });
177	  await fs.writeFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)), daten);
178	}
179	
180	export async function uploadLesen(dateiname) {
181	  return fs.readFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)));
182	}
183	
184	export async function uploadLoeschen(dateiname) {
185	  await fs.rm(path.join(UPLOAD_ORDNER, path.basename(dateiname)), { force: true });
186	}
