338	    const f = eigenerFall(db, n);
339	    if (!f) throw ungueltig("Bitte wählen Sie zuerst den Kontotyp.");
340	    if (!KYC_BEARBEITBAR.includes(f.status)) throw konflikt("Ihre Unterlagen liegen gerade zur Prüfung vor bzw. sind geprüft. Für Änderungen starten Sie bitte eine erneute Prüfung.");
341	    const def = KYC_DOKUMENTE[art];
342	    let fl = null;
343	    if (def.bezug === "flaeche") {
344	      fl = (db.flaechen || []).find((x) => x.id === v.kennung(flaecheId));
345	      if (!fl || fl.nutzerId !== n.id) throw verboten("Eigentumsnachweise nur für eigene Flächen.");
346	    }
347	    if (def.bezug === "vertreter") v.pflicht((f.vertreter || []).some((x) => x.id === String(personId || "")), "Bitte ordnen Sie den Ausweis einer vertretungsberechtigten Person zu.");
348	    const id = neueId("KD");
349	    const datei = `${id}-${sha256(`${id}${Math.random()}`).slice(0, 16)}.bin`;
350	    dateiSchreiben(datei, kycVerschluesseln(Buffer.from(daten), id));
351	    const d = {
