203	const RECHTSFORMEN = /\b(gmbh|ag|kg|og|ohg|gbr|ug|haftungsbeschrankt|mbh|co|eg|ev|se|sa|sarl|ltd|llc|inc|kgaa|stiftung|verein|genossenschaft|e\.?\s?u|eu)\b/g;
