205	export function nameNormalisieren(s) {
206	  return String(s || "")
207	    .toLowerCase()
208	    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
209	    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
210	    .replace(/\(demo\)|\(fiktiv\)|\(test\)/g, " ")
211	    .replace(/[^a-z0-9 ]+/g, " ")
212	    .replace(/\s+/g, " ")
213	    .trim();
214	}
