216	export const nameTokens = (s, { firma = false } = {}) => {
217	  let n = nameNormalisieren(s);
218	  if (firma) n = n.replace(RECHTSFORMEN, " ").replace(/\s+/g, " ").trim();
219	  return n.split(" ").filter((t) => t.length > 1 && !["und", "the", "von", "van", "der", "de", "dr", "mag", "ing", "prof"].includes(t));
220	};
