222	/** Stimmt der Kontoinhaber mit der geprüften Person bzw. Firma überein? */
223	export function kontoinhaberPasst(inhaber, { vorname = "", nachname = "", firma = "" } = {}) {
224	  const t = new Set(nameTokens(inhaber, { firma: !!firma }));
225	  if (!t.size) return false;
226	  if (firma) {
227	    const f = nameTokens(firma, { firma: true });
228	    return f.length > 0 && f.every((x) => t.has(x));
229	  }
230	  const soll = [...nameTokens(vorname), ...nameTokens(nachname)];
231	  const nach = nameTokens(nachname);
232	  if (!nach.length) return false;
233	  // Nachname vollständig, Vorname mindestens der erste Vorname (oder Initiale)
234	  const vor = nameTokens(vorname);
235	  const vornameOk = !vor.length || t.has(vor[0]) || [...t].some((x) => x.length === 1 && x === vor[0][0]);
236	  return soll.length > 0 && nach.every((x) => t.has(x)) && vornameOk;
237	}
