242	export function tageBis(datumIso, jetzt = new Date()) {
243	  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(datumIso || ""))) return null;
244	  return Math.floor((new Date(`${datumIso}T00:00:00Z`).getTime() - new Date(`${heuteIso(jetzt)}T00:00:00Z`).getTime()) / 86400000);
