376	export function kycFortschritt(anforderungen = []) {
377	  const pflicht = anforderungen.filter((x) => x.pflicht);
378	  const erfuellt = pflicht.filter((x) => x.erfuellt).length;
379	  return { erfuellt, gesamt: pflicht.length, quote: pflicht.length ? Math.round((erfuellt / pflicht.length) * 100) : 0, fehlend: pflicht.filter((x) => !x.erfuellt) };
