384	/**
385	 * Risikoeinstufung nach Regeln (Land, PEP, Struktur, Ticketgröße, Sanktionstreffer).
386	 * Liefert { stufe: niedrig|mittel|hoch, punkte, gruende[] }. Compliance kann manuell höher/niedriger einstufen (mit Begründung).
387	 */
388	export function kycRisiko(fall, einstellungen = kycEinstellungenStandard()) {
389	  const f = fall || {};
390	  const hoch = new Set((einstellungen.hochrisikoLaender || []).map((x) => String(x).toUpperCase()));
391	  const gruende = [];
392	  let punkte = 0;
393	  const plus = (n, g) => {
394	    punkte += n;
395	    gruende.push(g);
396	  };
397	  const dach = ["DE", "AT", "CH", "LI"];
398	  const eu = ["BE", "BG", "CY", "CZ", "DK", "EE", "ES", "FI", "FR", "GR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "NL", "PL", "PT", "RO", "SE", "SI", "SK", "IS", "NO"];
399	  const laender = [f.person?.adresse?.land, f.person?.staatsangehoerigkeit, f.firma?.land, ...(f.ubos || []).map((u) => u.wohnsitzland)].filter(Boolean).map((x) => String(x).toUpperCase());
400	  if (laender.some((l) => hoch.has(l))) plus(4, "Bezug zu einem Drittland mit hohem Risiko");
401	  else if (laender.some((l) => !dach.includes(l) && !eu.includes(l))) plus(2, "Bezug außerhalb EU/EWR/Schweiz");
402	  else if (laender.some((l) => !dach.includes(l))) plus(1, "Bezug zu einem EU/EWR-Land außerhalb DACH");
403	  if (f.pep?.istPep) plus(4, "Politisch exponierte Person (verstärkte Sorgfaltspflichten)");
404	  else if (f.pep?.naheStehend) plus(4, "Familienangehöriger/nahestehende Person einer PEP");
405	  if ((f.ubos || []).some((u) => u.pep)) plus(4, "Wirtschaftlich Berechtigter ist PEP");
406	  if (f.kontotyp === "unternehmen") {
407	    const ubos = f.ubos || [];
408	    if (!ubos.length || ubos.every((u) => u.kontrolleArt === "fiktiv")) plus(2, "Kein wirtschaftlich Berechtigter über Anteile ermittelbar (fiktiver wB)");
409	    if (f.firma?.mehrstufig) plus(2, "Mehrstufige Beteiligungsstruktur");
410	    if (f.firma?.treuhand) plus(2, "Treuhand-/Stiftungsstruktur");
411	  }
412	  const betrag = KYC_TICKETS[f.mittelherkunft?.ticket]?.betrag || 0;
413	  if (betrag > 5000000) plus(2, "Ticketgröße über 5 Mio. €");
414	  else if (betrag > 1000000) plus(1, "Ticketgröße über 1 Mio. €");
415	  if (f.sanktionen?.status === "treffer_pruefen" || f.sanktionen?.status === "bestaetigt") plus(4, "Möglicher Treffer im Sanktionslisten-Abgleich");
416	  const stufe = punkte >= 4 ? "hoch" : punkte >= 2 ? "mittel" : "niedrig";
417	  return { stufe, punkte, gruende };
418	}
