422	// ================================================================ Gating
423	
424	/** Geltung der Freigabe-Sperren: Einstellung > Umgebung > Standard (Produktion „alle“, Entwicklung „pilot“) */
425	export function kycGeltung(einstellungen = {}, env = {}) {
426	  const e = einstellungen?.geltung;
427	  if (["alle", "pilot", "aus"].includes(e)) return e;
428	  const u = String(env.PLATTFORM_KYC_GATING || "").toLowerCase();
429	  if (["alle", "pilot", "aus"].includes(u)) return u;
430	  if (u === "an" || u === "1") return "alle";
431	  return env.NODE_ENV === "production" ? "alle" : "pilot";
432	}
433	
434	/** Ist der Schritt für dieses Konto gesperrt, solange es nicht verifiziert ist? */
435	export function kycSchrittAktiv(schritt, kontoId, einstellungen = kycEinstellungenStandard(), env = {}) {
436	  const e = { ...kycEinstellungenStandard(), ...(einstellungen || {}) };
437	  if (!KYC_SCHRITTE[schritt] || e.gating?.[schritt] === false) return false;
438	  const g = kycGeltung(e, env);
439	  if (g === "aus") return false;
440	  if (g === "pilot") return (e.pilotKonten || []).includes(kontoId);
441	  return true;
442	}
