444	/**
445	 * Freigabe-Entscheidung aus einem (bereits ermittelten) KYC-Status.
446	 * status: Ergebnis von kycStatus(); extra: { flaecheId } für Auszahlungen.
447	 */
448	export function kycFreigabe(schritt, status, { aktiv = true, flaecheId = null } = {}) {
449	  const def = KYC_SCHRITTE[schritt];
450	  if (!def) return { ok: false, aktiv: true, gruende: ["Unbekannter Schritt."], hinweis: "" };
451	  if (!aktiv) return { ok: true, aktiv: false, gruende: [], hinweis: "" };
452	  const gruende = [];
453	  if (!status?.verifiziert) gruende.push(status?.status === "abgelaufen" ? "Die Verifizierung muss erneuert werden." : "Die Verifizierung ist nicht abgeschlossen.");
454	  if (schritt === "auszahlung") {
455	    if (!status?.bank?.geprueft) gruende.push("Es fehlt eine geprüfte Bankverbindung (IBAN, Kontoinhaber = verifizierte Person/Firma).");
456	    if (flaecheId && !(status?.eigentum || []).includes(flaecheId)) gruende.push("Für diese Fläche liegt kein geprüfter Eigentumsnachweis vor.");
457	  }
458	  return { ok: gruende.length === 0, aktiv: true, gruende, hinweis: gruende.length ? def.hinweis : "" };
459	}
