20	const ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };
21	const entschaerfen = (s) => String(s || "").replace(/&(#x?[0-9a-f]+|amp|lt|gt|quot|apos);/gi, (_, e) => {
22	  if (e[0] === "#") return String.fromCodePoint(e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10));
23	  return ENTITIES[e.toLowerCase()] || "";
24	});
