26	function attribute(tag) {
27	  const a = {};
28	  for (const m of tag.matchAll(/([\w:.-]+)\s*=\s*"([^"]*)"/g)) a[m[1].replace(/^.*:/, "")] = entschaerfen(m[2]);
29	  return a;
30	}
