32	/** EU-FSF-XML (v1.1) → [{ id, euRef, typ, namen[], geburtsdaten[], laender[], programm }] */
33	export function euXmlLesen(xml) {
34	  const text = String(xml || "");
35	  const eintraege = [];
36	  for (const m of text.matchAll(/<(?:\w+:)?sanctionEntity\b([^>]*)>([\s\S]*?)<\/(?:\w+:)?sanctionEntity>/g)) {
37	    const kopf = attribute(m[1]);
38	    const inhalt = m[2];
39	    const namen = [];
40	    for (const n of inhalt.matchAll(/<(?:\w+:)?nameAlias\b([^>]*?)\/?>/g)) {
41	      const a = attribute(n[1]);
42	      const ganz = a.wholeName || [a.firstName, a.middleName, a.lastName].filter(Boolean).join(" ");
43	      if (ganz && !namen.includes(ganz)) namen.push(ganz);
44	    }
45	    const geburtsdaten = [];
46	    for (const b of inhalt.matchAll(/<(?:\w+:)?birthdate\b([^>]*?)\/?>/g)) {
47	      const a = attribute(b[1]);
48	      const d = a.birthdate || (a.year ? `${a.year}${a.monthOfYear ? `-${String(a.monthOfYear).padStart(2, "0")}${a.dayOfMonth ? `-${String(a.dayOfMonth).padStart(2, "0")}` : ""}` : ""}` : "");
49	      if (d && !geburtsdaten.includes(d)) geburtsdaten.push(d);
50	    }
51	    const laender = [...new Set([...inhalt.matchAll(/countryIso2Code="([A-Z]{2})"/g)].map((x) => x[1]))];
52	    const typ = /<(?:\w+:)?subjectType\b[^>]*code="([^"]+)"/.exec(inhalt)?.[1] || "";
53	    const programm = /<(?:\w+:)?regulation\b[^>]*programme="([^"]+)"/.exec(inhalt)?.[1] || "";
54	    if (namen.length) eintraege.push({ id: String(kopf.logicalId || kopf.euReferenceNumber || eintraege.length + 1), euRef: kopf.euReferenceNumber || "", typ: typ === "person" ? "person" : typ ? "organisation" : "", namen, geburtsdaten, laender, programm });
55	  }
56	  return eintraege;
57	}
