59	function csvZeilen(text, trenner) {
60	  const zeilen = [];
61	  let zeile = [];
62	  let feld = "";
63	  let inQ = false;
64	  for (let i = 0; i < text.length; i++) {
65	    const c = text[i];
66	    if (inQ) {
67	      if (c === '"' && text[i + 1] === '"') { feld += '"'; i++; }
68	      else if (c === '"') inQ = false;
69	      else feld += c;
70	    } else if (c === '"') inQ = true;
71	    else if (c === trenner) { zeile.push(feld); feld = ""; }
72	    else if (c === "\n" || c === "\r") {
73	      if (c === "\r" && text[i + 1] === "\n") i++;
74	      zeile.push(feld); feld = "";
75	      if (zeile.some((x) => x !== "")) zeilen.push(zeile);
76	      zeile = [];
77	    } else feld += c;
78	  }
79	  zeile.push(feld);
80	  if (zeile.some((x) => x !== "")) zeilen.push(zeile);
81	  return zeilen;
82	}
