84	/** EU-FSF-CSV (v1.1, Semikolon; eine Zeile je Alias/Datum) → Einträge gruppiert nach Entity_LogicalId */
85	export function euCsvLesen(csv) {
86	  const text = String(csv || "").replace(/^﻿/, "");
87	  const trenner = (text.split(/\r?\n/)[0].match(/;/g) || []).length >= (text.split(/\r?\n/)[0].match(/,/g) || []).length ? ";" : ",";
88	  const zeilen = csvZeilen(text, trenner);
89	  if (!zeilen.length) return [];
90	  const kopf = zeilen[0].map((h) => h.trim());
91	  const spalte = (...namen) => {
92	    for (const n of namen) {
93	      const i = kopf.findIndex((h) => h.toLowerCase() === n.toLowerCase());
94	      if (i >= 0) return i;
95	    }
96	    return -1;
97	  };
98	  const iId = spalte("Entity_LogicalId", "id");
99	  const iRef = spalte("Entity_EU_ReferenceNumber", "euRef");
100	  const iName = spalte("NameAlias_WholeName", "name");
101	  const iVor = spalte("NameAlias_FirstName");
102	  const iNach = spalte("NameAlias_LastName");
103	  const iGeb = spalte("BirthDate_BirthDate", "geburtsdatum");
104	  const iJahr = spalte("BirthDate_Year");
105	  const iTyp = spalte("Entity_SubjectType", "Entity_SubjectType_ClassificationCode", "typ");
106	  const iProg = spalte("Entity_Regulation_Programme", "programm");
107	  const iLand = spalte("Citizenship_CountryIso2Code", "Address_CountryIso2Code", "land");
108	  if (iId < 0 || (iName < 0 && iNach < 0)) throw new Error("CSV-Kopfzeile unbekannt: Spalten Entity_LogicalId und NameAlias_WholeName erwartet.");
109	  const map = new Map();
110	  for (const z of zeilen.slice(1)) {
111	    const id = String(z[iId] || "").trim();
112	    if (!id) continue;
113	    const e = map.get(id) || { id, euRef: iRef >= 0 ? z[iRef] || "" : "", typ: "", namen: [], geburtsdaten: [], laender: [], programm: iProg >= 0 ? z[iProg] || "" : "" };
114	    const name = (iName >= 0 ? z[iName] : "") || [iVor >= 0 ? z[iVor] : "", iNach >= 0 ? z[iNach] : ""].filter(Boolean).join(" ");
115	    if (name && !e.namen.includes(name.trim())) e.namen.push(name.trim());
116	    const geb = (iGeb >= 0 ? z[iGeb] : "") || (iJahr >= 0 ? z[iJahr] : "");
117	    if (geb && !e.geburtsdaten.includes(geb.trim())) e.geburtsdaten.push(geb.trim());
118	    const land = iLand >= 0 ? String(z[iLand] || "").trim() : "";
119	    if (/^[A-Z]{2}$/.test(land) && !e.laender.includes(land)) e.laender.push(land);
120	    const typ = iTyp >= 0 ? String(z[iTyp] || "").toLowerCase() : "";
121	    if (typ && !e.typ) e.typ = typ === "person" || typ === "p" ? "person" : "organisation";
122	    map.set(id, e);
123	  }
124	  return [...map.values()].filter((e) => e.namen.length);
125	}
