129	/** Jaro-Winkler-Ähnlichkeit (0–1) */
130	export function jaroWinkler(a, b) {
131	  if (a === b) return a ? 1 : 0;
132	  if (!a || !b) return 0;
133	  const weite = Math.max(0, Math.floor(Math.max(a.length, b.length) / 2) - 1);
134	  const ta = new Array(a.length).fill(false);
135	  const tb = new Array(b.length).fill(false);
136	  let treffer = 0;
137	  for (let i = 0; i < a.length; i++) {
138	    for (let j = Math.max(0, i - weite); j < Math.min(b.length, i + weite + 1); j++) {
139	      if (tb[j] || a[i] !== b[j]) continue;
140	      ta[i] = tb[j] = true;
141	      treffer++;
142	      break;
143	    }
144	  }
145	  if (!treffer) return 0;
146	  let k = 0;
147	  let wechsel = 0;
148	  for (let i = 0; i < a.length; i++) {
149	    if (!ta[i]) continue;
150	    while (!tb[k]) k++;
151	    if (a[i] !== b[k]) wechsel++;
152	    k++;
153	  }
154	  const jaro = (treffer / a.length + treffer / b.length + (treffer - wechsel / 2) / treffer) / 3;
155	  let praefix = 0;
156	  while (praefix < 4 && a[praefix] && a[praefix] === b[praefix]) praefix++;
157	  return jaro + praefix * 0.1 * (1 - jaro);
158	}
