160	const tokens = (s) => nameNormalisieren(s).split(" ").filter((t) => t.length > 1);
161	
162	/**
163	 * Namensähnlichkeit unabhängig von Reihenfolge: jedes Token des kürzeren Namens sucht sein bestes Gegenstück.
164	 * Mittelwert der besten Paare, Abzug bei fehlenden Tokens (z. B. nur Nachname gleich).
165	 */
166	export function namensAehnlichkeit(a, b) {
167	  const ta = tokens(a);
168	  const tb = tokens(b);
169	  if (!ta.length || !tb.length) return 0;
170	  if (ta.join(" ") === tb.join(" ")) return 1;
171	  const [kurz, lang] = ta.length <= tb.length ? [ta, tb] : [tb, ta];
172	  const frei = [...lang];
173	  let summe = 0;
174	  for (const t of kurz) {
175	    let best = 0;
176	    let bi = -1;
177	    frei.forEach((x, i) => {
178	      const s = jaroWinkler(t, x);
179	      if (s > best) { best = s; bi = i; }
180	    });
181	    summe += best;
182	    if (bi >= 0) frei.splice(bi, 1);
183	  }
184	  const deckung = kurz.length / lang.length;
185	  return (summe / kurz.length) * (0.85 + 0.15 * deckung);
186	}
