188	function geburtsdatumVergleich(soll, liste = []) {
189	  const s = String(soll || "").slice(0, 10);
190	  if (!s || !liste.length) return "unbekannt";
191	  if (liste.some((d) => d === s)) return "gleich";
192	  if (liste.some((d) => d.length === 4 && s.startsWith(d))) return "jahr";
193	  if (liste.some((d) => d.slice(0, 4) === s.slice(0, 4))) return "jahr";
194	  return "abweichend";
195	}
