197	/**
198	 * Person/Firma gegen die Liste prüfen.
199	 * pruefling: { name, geburtsdatum?, art: person|organisation, rolle?: "Person"|"Wirtschaftlich Berechtigter"|… }
200	 * Liefert Treffer [{ eintragId, euRef, name, score, geburtsdatum: gleich|jahr|abweichend|unbekannt, programm }] ≥ Schwelle.
201	 */
202	export function sanktionsAbgleich(pruefling, eintraege = [], { schwelle = 0.88 } = {}) {
203	  const treffer = [];
204	  const name = pruefling?.name || "";
205	  if (tokens(name).length === 0) return treffer;
206	  for (const e of eintraege) {
207	    if (pruefling.art === "organisation" && e.typ === "person") continue;
208	    if (pruefling.art === "person" && e.typ && e.typ !== "person") continue;
209	    let best = 0;
210	    let bestName = "";
211	    for (const n of e.namen || []) {
212	      const s = namensAehnlichkeit(name, n);
213	      if (s > best) { best = s; bestName = n; }
214	    }
215	    if (best < schwelle - 0.08) continue;
216	    const gd = pruefling.art === "person" ? geburtsdatumVergleich(pruefling.geburtsdatum, e.geburtsdaten) : "unbekannt";
217	    let score = best;
218	    if (gd === "gleich") score = Math.min(1, score + 0.08);
219	    else if (gd === "jahr") score = Math.min(1, score + 0.03);
220	    else if (gd === "abweichend") score -= 0.12;
221	    if (score >= schwelle) treffer.push({ eintragId: e.id, euRef: e.euRef || "", name: bestName, score: Math.round(score * 1000) / 1000, geburtsdatum: gd, programm: e.programm || "", pruefling: pruefling.rolle || "" });
222	  }
223	  return treffer.sort((a, b) => b.score - a.score).slice(0, 10);
224	}
