226	/** Alle prüfpflichtigen Namen eines KYC-Falls (Person, Firma, wirtschaftlich Berechtigte, Vertreter) */
227	export function prueflingeAusFall(fall) {
228	  const f = fall || {};
229	  const liste = [];
230	  const p = f.person || {};
231	  if (p.vorname || p.nachname) liste.push({ name: `${p.vorname || ""} ${p.nachname || ""}`.trim(), geburtsdatum: p.geburtsdatum, art: "person", rolle: "Person" });
232	  if (f.kontotyp === "unternehmen" && f.firma?.name) liste.push({ name: f.firma.name, art: "organisation", rolle: "Unternehmen" });
233	  for (const u of f.ubos || []) liste.push({ name: `${u.vorname || ""} ${u.nachname || ""}`.trim(), geburtsdatum: u.geburtsdatum, art: "person", rolle: "Wirtschaftlich Berechtigter" });
234	  for (const x of f.vertreter || []) liste.push({ name: `${x.vorname || ""} ${x.nachname || ""}`.trim(), geburtsdatum: x.geburtsdatum, art: "person", rolle: "Vertreter" });
235	  const gesehen = new Set();
236	  return liste.filter((x) => {
237	    const k = `${nameNormalisieren(x.name)}|${x.geburtsdatum || ""}|${x.art}`;
238	    if (!x.name || gesehen.has(k)) return false;
239	    gesehen.add(k);
240	    return true;
241	  });
242	}
