103	/** Download-Dateiname mit „Wasserzeichen“ (Empfänger + Datum) – ASCII-sicher, Endung bleibt */
104	export function wasserzeichenName(name, empfaenger, am = new Date()) {
105	  const s = String(name || "dokument.pdf");
106	  const punkt = s.lastIndexOf(".");
107	  const basis = (punkt > 0 ? s.slice(0, punkt) : s).trim();
108	  const endung = punkt > 0 ? s.slice(punkt) : "";
109	  const wer = [empfaenger?.vorname, empfaenger?.nachname].filter(Boolean).join(" ").replace(/\s*\(demo\)\s*/i, " Demo").trim() || "Empfaenger";
110	  const tag = new Date(am).toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });
111	  const sauber = (x) => x.replace(/[\\/:*?"<>|]+/g, "_").replace(/\s+/g, " ").trim();
112	  return `${sauber(basis)} - vertraulich fuer ${sauber(wer)} ${tag}${endung}`.slice(0, 180);
113	}
