117	const MUSTER = [
118	  /[A-Z0-9._%+-]{1,64}@[A-Z0-9.-]{1,120}\.[A-Z]{2,24}/gi, // E-Mail
119	  /\b(?:https?:\/\/|www\.)\S+/gi, // Links
120	  /(?:\+|00)\d[\d ()/.-]{6,20}\d/g, // internationale Rufnummer
121	  /\b0\d{2,5}(?:[ /.-]?\d){4,14}\b/g, // nationale Rufnummer
