137	/** Pseudonym je Reihenfolge: 0 → „A“, 25 → „Z“, 26 → „AA“ */
138	export function pseudonymBuchstabe(i) {
139	  let n = Math.max(0, i | 0);
140	  let s = "";
141	  do {
142	    s = String.fromCharCode(65 + (n % 26)) + s;
143	    n = Math.floor(n / 26) - 1;
144	  } while (n >= 0);
145	  return s;
146	}
