232	  const { rolle } = rolleIm(db, n, p);
233	  const pseudo = pseudonyme(db, p.id);
234	  let liste = db.dealroom.fragen.filter((f) => f.projektId === p.id);
235	  if (rolle === "anbieter") liste = liste.filter((f) => ["freigegeben", "beantwortet", "veroeffentlicht"].includes(f.status));
236	  if (rolle === "investor") liste = liste.filter((f) => f.investorId === n.id || (f.status === "veroeffentlicht" && f.oeffentlich));
237	  const reihenfolge = { eingereicht: 0, beantwortet: 1, freigegeben: 2, veroeffentlicht: 3, abgelehnt: 4 };
238	  liste.sort((a, b) => (reihenfolge[a.status] ?? 9) - (reihenfolge[b.status] ?? 9) || String(b.erstelltAm).localeCompare(String(a.erstelltAm)));
239	  const fragen = liste.map((f) => frageAusgabe(db, f, rolle, n, pseudo));
240	  return {
241	    rolle,
242	    fragen,
243	    zaehler: {
244	      gesamt: fragen.length,
