308	    const p = projektLaden(db, f.projektId);
309	    const { rolle } = rolleIm(db, n, p, { investorFehler: true });
310	    const admin = rolle === "admin";
311	    if (aktion !== "antworten" && !admin) throw verboten("Nur für das Backoffice.");
312	    if (aktion === "antworten" && !["admin", "anbieter"].includes(rolle)) throw verboten("Antworten gibt der Anbieter des Projekts.");
313	    const investor = nutzerById(db, f.investorId);
