339	      benachrichtigen(db, investor, { art: "nda", titel: `Frage nicht zugelassen: ${p.titel}`, text: grund, link: dealLink(p.id, "qa"), objektArt: "interesse", objektId: f.interesseId }, { mailText: MAIL_DEAL });
340	    } else if (aktion === "antworten") {
341	      if (!["freigegeben", "beantwortet"].includes(f.status)) throw konflikt(f.status === "eingereicht" ? "Die Frage ist noch in der Moderation." : "Die Frage ist bereits abgeschlossen.");
342	      const roh = v.mehrzeilig(daten.antwort, 5000);
343	      v.pflicht(roh.length >= 5, "Bitte geben Sie eine Antwort ein (mind. 5 Zeichen).");
