354	          benachrichtigen(db, adm, { art: "nachricht", titel: `Antwort zur Freigabe: ${p.titel}`, text: `${QA_KATEGORIEN[f.kategorie]} · ${a.text.slice(0, 140)}`, link: dealLink(p.id, "qa"), objektArt: "projekt", objektId: p.id }, { mailText: MAIL_DEAL });
355	        }
356	      }
