371	        }
372	      }
373	    } else if (aktion === "zurueckgeben") {
374	      if (f.status !== "beantwortet") throw konflikt("Es liegt keine Antwort vor.");
375	      const kommentar = v.mehrzeilig(daten.kommentar, 500);
