379	      schritt("freigegeben", `Antwort zurückgegeben: ${kommentar}`);
380	      benachrichtigen(db, anbieter, { art: "nachricht", titel: `Rückfrage zu Ihrer Antwort: ${p.titel}`, text: kommentar.slice(0, 200), link: dealLink(p.id, "qa"), objektArt: "projekt", objektId: p.id }, { mailText: MAIL_DEAL });
381	    } else if (aktion === "frist") {
