397	/** Effektiver Status (Fristablauf wird beim Lesen erkannt) */
398	function verfahrenStatus(db, vf) {
399	  const p = db.projekte.find((x) => x.id === vf.projektId);
400	  if (vf.status === "zuschlag" && p?.status === "verkauft") return "abgeschlossen";
401	  if (vf.status === "laufend" && !rundeOffen(aktuelleRunde(vf))) return "auswertung";
402	  return vf.status;
