427	    zeitplan: g.zeitplan,
428	    gueltigBis: g.gueltigBis || "",
429	    status: g.status,
430	    am: g.am,
431	    version: g.version,
432	  };
433	  if (rolle === "investor") return basis;
434	  return { ...basis, interesseId: rolle === "admin" ? g.interesseId : undefined, von: investorAnzeige(db, rolle, g.projektId, g.interesseId, pseudo), historie: rolle === "admin" ? g.historie || [] : undefined };
