437	function verfahrenAusgabe(db, vf, rolle, n, p) {
438	  const r = aktuelleRunde(vf);
439	  const status = verfahrenStatus(db, vf);
440	  const out = {
441	    id: vf.id,
442	    projektId: vf.projektId,
443	    status,
444	    pflicht: vf.pflicht,
445	    hinweis: vf.hinweis || "",
446	    erstelltAm: vf.erstelltAm,
447	    runde: { nr: r.nr, art: r.art, label: RUNDEN_ARTEN[r.art]?.label, start: r.start, frist: r.frist, offen: rundeOffen(r), beendetAm: r.beendetAm || null },
448	    runden: vf.runden.map((x) => ({ nr: x.nr, art: x.art, label: RUNDEN_ARTEN[x.art]?.label, start: x.start, frist: x.frist, beendetAm: x.beendetAm || null, teilnehmerAnzahl: rolle === "investor" ? undefined : x.teilnehmer.length })),
449	    anbieterFreigabe: !!vf.anbieterFreigabe,
450	    zuschlag: null,
451	  };
452	  const pseudo = pseudonyme(db, p.id);
453	  const gebote = db.dealroom.gebote.filter((g) => g.verfahrenId === vf.id && g.status !== "zurueckgezogen");
454	  if (rolle === "investor") {
455	    const i = interesseVon(db, p.id, n.id);
456	    out.zugelassen = !!i && r.teilnehmer.includes(i.id) && ["laufend"].includes(status);
457	    out.eigeneGebote = db.dealroom.gebote.filter((g) => g.verfahrenId === vf.id && g.investorId === n.id).sort((a, b) => b.am.localeCompare(a.am)).map((g) => gebotAusgabe(db, g, rolle, pseudo, p));
458	    out.zuschlagEigen = vf.zuschlag ? vf.zuschlag.interesseId === i?.id : null;
459	    return out;
460	  }
461	  if (vf.zuschlag) out.zuschlag = { am: vf.zuschlag.am, preisGesamt: vf.zuschlag.preisGesamt, von: investorAnzeige(db, rolle, p.id, vf.zuschlag.interesseId, pseudo), gebotId: rolle === "admin" ? vf.zuschlag.gebotId : undefined, interesseId: rolle === "admin" ? vf.zuschlag.interesseId : undefined };
462	  const zeigen = rolle === "admin" || vf.anbieterFreigabe;
463	  out.matrix = zeigen
464	    ? gebote
465	        .map((g) => gebotAusgabe(db, g, rolle, pseudo, p))
466	        .sort((a, b) => b.runde - a.runde || (b.preisGesamt || 0) - (a.preisGesamt || 0))
467	    : null;
468	  out.geboteAnzahl = rolle === "admin" || vf.anbieterFreigabe ? gebote.filter((g) => g.runde === r.nr).length : undefined;
469	  if (rolle === "admin") {
470	    out.teilnehmer = r.teilnehmer.map((iid) => {
471	      const g = gebote.find((x) => x.interesseId === iid && x.runde === r.nr);
472	      return { ...investorAnzeige(db, "admin", p.id, iid, pseudo), interesseId: iid, geboten: !!g, gebotAm: g?.am || null };
473	    });
474	    out.erinnertAm = r.erinnertAm || null;
475	    out.verlauf = vf.verlauf || [];
476	  }
477	  return out;
478	}
