480	function erinnern(db, vf, p, { sofort = false } = {}) {
481	  const r = aktuelleRunde(vf);
482	  if (!rundeOffen(r)) return 0;
483	  const bis = new Date(r.frist).getTime() - Date.now();
484	  if (!sofort && (r.erinnertAm || bis > ERINNERUNG_STUNDEN * 3600e3)) return 0;
485	  let anzahl = 0;
486	  for (const iid of r.teilnehmer) {
487	    const hat = db.dealroom.gebote.some((g) => g.verfahrenId === vf.id && g.runde === r.nr && g.interesseId === iid && g.status === "abgegeben");
488	    if (hat) continue;
489	    const i = db.interessen.find((x) => x.id === iid);
490	    if (!i) continue;
491	    benachrichtigen(db, nutzerById(db, i.investorId), { art: "nda", titel: `Erinnerung Angebotsfrist: ${p.titel}`, text: `${RUNDEN_ARTEN[r.art].label} bis ${new Date(r.frist).toLocaleString("de-DE", { timeZone: "Europe/Vienna", dateStyle: "short", timeStyle: "short" })}`, link: dealLink(p.id, "bieter"), objektArt: "interesse", objektId: i.id }, { mailText: "Eine Angebotsfrist im Deal-Room eines Projekts läuft bald ab. Details finden Sie im Portal." });
492	    anzahl++;
493	  }
494	  r.erinnertAm = jetzt();
495	  return anzahl;
496	}
