498	/** Bieterverfahren eines Projekts (aktuellstes) in der Sicht der Rolle – oder null */
499	export async function bieterverfahren(n, projektId) {
500	  let db = await lesenBereit();
501	  const p = projektLaden(db, projektId);
502	  const { rolle } = rolleIm(db, n, p);
503	  let vf = [...db.dealroom.verfahren].reverse().find((x) => x.projektId === p.id) || null;
504	  if (vf && vf.status === "laufend" && !aktuelleRunde(vf).erinnertAm && rundeOffen(aktuelleRunde(vf)) && new Date(aktuelleRunde(vf).frist).getTime() - Date.now() <= ERINNERUNG_STUNDEN * 3600e3) {
505	    await aendernBereit((d) => {
506	      const x = d.dealroom.verfahren.find((y) => y.id === vf.id);
507	      if (x) erinnern(d, x, projektLaden(d, p.id));
508	    });
509	    db = await lesen();
510	    vf = db.dealroom.verfahren.find((x) => x.id === vf.id);
511	  }
512	  return { rolle, verfahren: vf ? verfahrenAusgabe(db, vf, rolle, n, projektLaden(db, p.id)) : null, projekt: { id: p.id, mwp: p.mwp, status: p.status, titel: p.titel } };
513	}
