759	/** Datenraum eines Projekts: Ordner nach Standard-Index, Versionen, Freigabestufen */
760	export async function datenraum(n, projektId, { besuch = false, ip = "" } = {}) {
761	  let db = await lesenBereit();
762	  const p = projektLaden(db, projektId);
763	  const { rolle, interesse } = rolleIm(db, n, p);
764	  if (rolle === "investor" && besuch) {
765	    const letzte = db.dealroom.zugriffe.findLast?.((z) => z.projektId === p.id && z.nutzerId === n.id && z.art === "datenraum");
766	    if (!letzte || Date.now() - new Date(letzte.am).getTime() > 30 * 60e3) {
767	      await aendernBereit((d) => zugriffLoggen(d, { projektId: p.id, nutzerId: n.id, interesseId: interesse.id, art: "datenraum", ip }));
768	      db = await lesen();
769	    }
770	  }
771	  const stufe = rolle === "investor" ? investorStufe(interesse, { verbindlichZugelassen: verbindlichZugelassen(db, interesse) }) : 2;
772	  let doks = db.dokumente.filter((d) => d.bezugArt === "projekt" && d.bezugId === p.id);
773	  if (rolle === "investor") doks = doks.filter((d) => d.kategorie === "datenraum");
774	  const metas = new Map(doks.map((d) => [d.id, metaVon(db, d)]));
775	  const nachfolger = new Map();
776	  for (const d of doks) {
777	    const vv = metas.get(d.id).versionVon;
778	    if (vv && metas.has(vv)) nachfolger.set(vv, d.id);
779	  }
780	  const aktuelle = doks.filter((d) => !nachfolger.has(d.id));
781	  const byId = new Map(doks.map((d) => [d.id, d]));
782	  const eintraege = aktuelle.map((d) => {
783	    const kette = [];
784	    let x = d;
785	    const gesehen = new Set();
786	    while (x && !gesehen.has(x.id)) {
787	      gesehen.add(x.id);
788	      kette.push(x);
789	      const vv = metas.get(x.id).versionVon;
790	      x = vv ? byId.get(vv) : null;
791	    }
792	    const m = metas.get(d.id);
793	    const gesperrt = rolle === "investor" && m.stufe > stufe;
794	    const version = kette.length;
795	    return {
796	      id: d.id,
797	      name: d.name,
798	      mime: d.mime,
799	      groesse: d.groesse,
800	      am: d.am,
801	      kategorie: d.kategorie,
802	      checkliste: d.checkliste || "",
803	      ordner: m.ordner,
804	      stufe: m.stufe,
805	      version,
806	      gesperrt,
807	      versionen: kette.slice(1).map((k, idx) => ({ id: k.id, name: k.name, am: k.am, groesse: k.groesse, version: version - idx - 1, gesperrt: rolle === "investor" && metas.get(k.id).stufe > stufe })),
808	      eigenerUpload: d.hochgeladenVon === n.id,
809	    };
810	  });
811	  const ordner = DATENRAUM_ORDNER.map((o) => ({ ...o, dokumente: eintraege.filter((e) => e.ordner === o.id).sort((a, b) => a.name.localeCompare(b.name, "de")) }));
812	  return { rolle, stufe, ordner, anzahl: eintraege.length, gesperrt: eintraege.filter((e) => e.gesperrt).length, projekt: { id: p.id, titel: p.titel } };
813	}
