824	    const alt = metaVon(db, d);
825	    const neu = { ...alt };
826	    if (daten.ordner !== undefined) neu.ordner = v.auswahl(daten.ordner, DATENRAUM_ORDNER_IDS, alt.ordner);
827	    if (daten.stufe !== undefined) neu.stufe = Number(daten.stufe) === 2 ? 2 : 1;
