945	    const zuschlag = eigene.some((g) => g.status === "zuschlag");
946	    const auto = pipelineSpalte(i, { gebotAbgegeben: eigene.length > 0, zuschlag });
947	    const notiz = notizen.get(p.id);
948	    const letztes = eigene.sort((a, b) => b.am.localeCompare(a.am))[0];
949	    if (!i.gemerkt && i.status === "gemerkt" && !notiz) continue;
950	    karten.push({
951	      interesseId: i.id,
