953	      statusLabel: statusLabel("interesse", i.status),
954	      spalteAuto: auto,
955	      spalte: notiz?.spalte && PIPELINE_SPALTEN_IDS.includes(notiz.spalte) ? notiz.spalte : auto,
956	      manuell: !!(notiz?.spalte && notiz.spalte !== auto),
