960	      gebote: eigene.length,
961	      letztesGebot: letztes ? { preisGesamt: gebotGesamt(letztes, p.mwp), runde: letztes.runde, status: letztes.status, am: letztes.am } : null,
962	      dealroom: DATENRAUM_STATUS.includes(i.status),
963	      geaendertAm: [i.geaendertAm, notiz?.geaendertAm].filter(Boolean).sort().pop(),
964	    });
