966	  karten.sort((a, b) => String(b.geaendertAm).localeCompare(String(a.geaendertAm)));
967	  const aktiv = karten.filter((k) => AKTIVE_SPALTEN.includes(k.spalteAuto));
968	  const mitPreis = aktiv.filter((k) => k.projekt.preisModus !== "anfrage" && (k.projekt.preisProKwp || k.projekt.preis) && k.projekt.mwp);
969	  const kwpSumme = mitPreis.reduce((s, k) => s + k.projekt.mwp * 1000, 0);
970	  const preisSumme = mitPreis.reduce((s, k) => s + (k.projekt.preisModus === "proKwp" ? k.projekt.preisProKwp * k.projekt.mwp * 1000 : k.projekt.preis), 0);
971	  const verteilung = (feld) => {
