      "Content-Type": meta.mime,
      "Content-Length": String(daten.length),
      "Content-Disposition": `${anzeigen ? "inline" : "attachment"}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(dateiname)}`,
