727	/**
728	 * Aktion im Closing-Raum (Backoffice):
729	 *   signing_punkt { schluessel, erledigt, notiz } · signing · cp { schluessel, status, nachweis } · cp_neu { label, verantwortlich, frist, text }
730	 *   zahlung_eingang { datum, betrag } · closing · uebergabe { schluessel, erledigt, notiz } · abbrechen { grund }
731	 */
732	export async function clAktion(n, id, daten = {}) {
733	  schreibNoetig(n, "closing", "Deal-Abschluss (Closing)");
734	  const aktion = v.auswahl(daten.aktion, ["signing_punkt", "signing", "cp", "cp_neu", "zahlung_eingang", "closing", "uebergabe", "abbrechen"], "");
735	  if (!aktion) throw ungueltig("Unbekannte Aktion.");
736	  if (aktion === "closing") return closingVollziehen(n, id, daten);
737	  return aendernBereit((db) => {
738	    const c = closingLaden(db, id);
739	    const p = db.projekte.find((x) => x.id === c.projektId);
740	    if (aktion === "uebergabe") {
741	      if (c.status !== "vollzogen") throw konflikt("Die Übergabe folgt nach dem Closing.");
742	      const u = c.uebergabe.find((x) => x.schluessel === daten.schluessel);
743	      if (!u) throw ungueltig("Unbekannter Punkt.");
744	      u.erledigt = v.wahr(daten.erledigt);
745	      u.am = u.erledigt ? heute() : "";
746	      u.vonId = n.id;
747	      u.notiz = v.text(daten.notiz, 300);
748	      verlauf(c, n, `Übergabe: ${UEBERGABE_PUNKTE.find((x) => x.schluessel === u.schluessel)?.label} ${u.erledigt ? "erledigt" : "offen"}.`);
749	    } else {
750	      if (!CL_OFFEN.includes(c.status)) throw konflikt("Der Closing-Raum ist abgeschlossen.");
751	      if (aktion === "signing_punkt") {
752	        const def = SIGNING_PUNKTE.find((x) => x.schluessel === daten.schluessel);
753	        if (!def) throw ungueltig("Unbekannter Punkt.");
754	        if (def.auto) throw konflikt("Dieser Punkt wird automatisch aus dem KYC-Modul gesetzt.");
755	        if (c.status !== "vorbereitung") throw konflikt("Das Signing ist bereits erfolgt.");
756	        const s = c.signing.punkte.find((x) => x.schluessel === def.schluessel);
757	        s.erledigt = v.wahr(daten.erledigt);
758	        s.am = s.erledigt ? heute() : "";
759	        s.vonId = n.id;
760	        s.notiz = v.text(daten.notiz, 300);
761	        verlauf(c, n, `Signing-Checkliste: ${def.label} ${s.erledigt ? "erledigt" : "offen"}.`);
762	      } else if (aktion === "signing") {
763	        const kyc = kycFuer(db, c);
764	        const pr = signingPruefen(c, kyc);
765	        if (!kyc.kontaktFrei) pr.gruende.push("Kontaktfreigabe (Deal-Room) fehlt – vor dem Signing müssen sich die Parteien namentlich kennen.");
766	        if (pr.gruende.length) throw new PlattformFehler(409, `Signing nicht möglich: ${pr.gruende.join(" ")}`, kyc.kycKaeufer && kyc.kycVerkaeufer ? "signing" : "kyc");
767	        c.status = "signing";
768	        c.signingAm = /^20\d\d-\d\d-\d\d$/.test(String(daten.datum || "")) && daten.datum <= heute() ? daten.datum : heute();
769	        oeffentlich(c, n, "Signing bestätigt – Kaufvertrag unterzeichnet. Jetzt folgen die Closing Conditions.");
770	        beteiligteMelden(db, c, { titel: `Signing bestätigt: ${p?.titel || ""}`, text: "Der Kaufvertrag ist unterzeichnet. Offene Bedingungen und Fristen sehen Sie im Closing-Raum." });
771	      } else if (aktion === "cp") {
772	        const x = c.cps.find((y) => y.schluessel === daten.schluessel);
773	        if (!x) throw ungueltig("Unbekannte Bedingung.");
774	        const st = v.auswahl(daten.status, Object.keys(CP_STATUS), "");
775	        if (!st) throw ungueltig("Unbekannter Status.");
776	        const nachweis = v.text(daten.nachweis ?? x.nachweis, 300);
777	        if (st === "erfuellt") v.pflicht(nachweis.length >= 3, "Bitte einen Nachweis angeben (z. B. Dokument, Datum, Aktenzeichen).");
778	        if (st === "verzichtet") v.pflicht(v.text(daten.nachweis, 300).length >= 5, "Bitte den Verzicht begründen (wer hat verzichtet, Datum).");
779	        x.status = st;
780	        x.nachweis = nachweis;
781	        x.erfuelltAm = ["erfuellt", "verzichtet"].includes(st) ? heute() : "";
782	        x.vonId = n.id;
783	        if (daten.frist && /^20\d\d-\d\d-\d\d$/.test(daten.frist)) x.frist = daten.frist;
784	        oeffentlich(c, n, `Bedingung „${x.label}“: ${CP_STATUS[st].label}.`);
785	      } else if (aktion === "cp_neu") {
786	        const label = v.text(daten.label, 160);
787	        v.pflicht(label.length >= 5, "Bitte die Bedingung beschreiben (mind. 5 Zeichen).");
788	        const ver = v.auswahl(daten.verantwortlich, Object.keys(CL_VERANTWORTLICH), "oekoinvest");
789	        c.cps.push({ schluessel: `eigen_${c.cps.length + 1}`, reihenfolge: c.cps.length + 1, label, text: v.text(daten.text, 300), verantwortlich: ver, frist: /^20\d\d-\d\d-\d\d$/.test(String(daten.frist || "")) ? daten.frist : "", status: "offen", nachweis: "", erfuelltAm: "", vonId: n.id, gemeldetVonId: null });
790	        oeffentlich(c, n, `Neue Bedingung: ${label}.`);
791	      } else if (aktion === "zahlung_eingang") {
792	        if (c.status !== "signing") throw konflikt("Der Kaufpreis wird nach dem Signing gezahlt.");
793	        const datum = /^20\d\d-\d\d-\d\d$/.test(String(daten.datum || "")) ? daten.datum : heute();
794	        if (datum > heute()) throw ungueltig("Das Eingangsdatum darf nicht in der Zukunft liegen.");
795	        const betrag = v.zahl(daten.betrag, { min: 1, max: 1e11 }) ?? c.kaufpreis;
796	        const faelligJetzt = (c.meilensteine || []).length ? c.kaufpreis - c.meilensteine.filter((m) => !m.bezahltAm).reduce((s, m) => s + m.betrag, 0) : c.kaufpreis;
797	        if (betrag + 1 < Math.max(0, faelligJetzt)) throw ungueltig(`Eingegangen sind ${Math.round(betrag).toLocaleString("de-DE")} € – zum Closing fällig sind ${Math.round(faelligJetzt).toLocaleString("de-DE")} €.`);
798	        c.zahlung = { ...c.zahlung, eingangAm: datum, betrag: Math.round(betrag), bestaetigtVonId: n.id };
799	        oeffentlich(c, n, `Zahlungseingang bestätigt${c.zahlung.treuhand ? " (Treuhand-/Notaranderkonto)" : ""}.`);
800	      } else if (aktion === "abbrechen") {
801	        const grund = v.text(daten.grund, 300);
802	        v.pflicht(grund.length >= 5, "Bitte einen Grund angeben.");
803	        c.status = "abgebrochen";
804	        oeffentlich(c, n, `Closing abgebrochen: ${grund}`);
805	        beteiligteMelden(db, c, { titel: `Deal-Abschluss abgebrochen: ${p?.titel || ""}`, text: "Der Closing-Raum wurde geschlossen." });
806	      }
807	    }
808	    c.geaendertAm = jetzt();
809	    protokoll(db, n, `closing_${aktion}`, "closing", c.id, `${aktion}${daten.schluessel ? ` ${daten.schluessel}` : ""}`);
810	    return closingAusgabe(db, n, c, { detail: true });
811	  });
812	}
