814	/** Closing vollziehen: Prüfung → Projekt „verkauft“ (Provision) → Provisionsrechnung (Finanzen) → Status vollzogen */
815	async function closingVollziehen(n, id, { ip = "" } = {}) {
816	  let db = await lesenBereit();
817	  const c0 = closingLaden(db, id);
818	  const kyc0 = kycFuer(db, c0);
819	  const pr = closingPruefen(c0, kyc0);
820	  if (!pr.ok) throw new PlattformFehler(409, `Closing nicht möglich: ${pr.gruende.join(" ")}`, kyc0.kycKaeufer && kyc0.kycVerkaeufer ? "closing" : "kyc");
821	  const p0 = db.projekte.find((x) => x.id === c0.projektId);
822	  // 1. Projekt → verkauft (Automat im Kern-Backend legt die Provision an)
823	  if (p0 && p0.status !== "verkauft") await statusWechsel(n, { art: "projekt", id: p0.id, nach: "verkauft", als: "admin", extra: { interesseId: c0.interesseId, kaufpreis: c0.kaufpreis }, ip });
824	  // 2. Provisionsrechnung über das Finanzen-Modul (Lauf „provision“)
825	  let rechnungFehler = "";
826	  try {
827	    const fin = await import("./finanzen");
828	    const kern = await import("./finanzen-kern");
829	    await fin.abrechnungslauf(kern.SYSTEM_FINANZEN, { art: "provision" });
830	  } catch (e) {
831	    rechnungFehler = e?.message || "unbekannt";
832	    console.warn("[plattform-demo] Provisionsrechnung beim Closing nicht erzeugt:", rechnungFehler);
833	  }
834	  // 3. Closing abschließen
835	  return aendern((d) => {
836	    const c = closingLaden(d, id);
837	    if (c.status === "vollzogen") return closingAusgabe(d, n, c, { detail: true });
838	    const pv = d.provisionen.filter((x) => x.projektId === c.projektId && x.interesseId === c.interesseId).sort((a, b) => String(b.erstelltAm).localeCompare(String(a.erstelltAm)))[0];
839	    c.provisionId = pv?.id || null;
840	    c.status = "vollzogen";
841	    c.vollzogenAm = heute();
842	    const beleg = pv ? (d.finanzen?.belege || []).find((b) => b.schluessel === `PV:${pv.id}` && b.status !== "storniert") : null;
843	    oeffentlich(c, n, "Closing vollzogen – Kaufgegenstand übergeht auf den Käufer. Übergabe-Checkliste ist offen.");
844	    verlauf(c, n, pv ? `Provision ${pv.id} (${pv.betrag} €) angelegt${beleg ? `, Provisionsrechnung ${beleg.nummer}` : rechnungFehler ? ` – Rechnung beim nächsten Lauf (${rechnungFehler})` : " – Rechnung folgt im nächsten Abrechnungslauf"}.` : "Keine Provision gefunden (Projekt bereits vorher verkauft?).");
845	    c.geaendertAm = jetzt();
846	    const p = d.projekte.find((x) => x.id === c.projektId);
847	    beteiligteMelden(d, c, { titel: `Closing vollzogen: ${p?.titel || ""}`, text: "Der Deal ist abgeschlossen. Übergabe und Abschlussbericht finden Sie im Closing-Raum." });
848	    for (const a of aktiveAdmins(d).filter((x) => darfLesen(x, "provisionen")).slice(0, 5)) benachrichtigen(d, a, { art: "status", titel: `Closing vollzogen: ${p?.titel || ""}`, text: beleg ? `Provisionsrechnung ${beleg.nummer} erzeugt.` : "Provisionsrechnung prüfen.", link: `/portal/admin/closing/${c.id}`, objektArt: "closing", objektId: c.id }, { mail: false });
849	    protokoll(d, n, "closing_vollzogen", "closing", c.id, `Closing ${c.id} vollzogen (${c.kaufpreis} €)`, ip);
850	    return closingAusgabe(d, n, c, { detail: true });
851	  });
852	}
