96	export function cpsAnlegen(struktur, { loiBedingungen = [], heute = new Date().toISOString().slice(0, 10) } = {}) {
97	  const liste = [...CP_STANDARD.gemeinsam, ...(CP_STANDARD[struktur] || [])];
98	  for (const b of loiBedingungen || []) if (CP_AUS_LOI[b] && !liste.some((c) => c.schluessel === CP_AUS_LOI[b].schluessel)) liste.push(CP_AUS_LOI[b]);
99	  return liste.map((c, i) => ({ schluessel: c.schluessel, reihenfolge: i + 1, label: c.label, text: c.text, verantwortlich: c.verantwortlich, frist: plusTage(heute, c.fristTage), status: "offen", nachweis: "", erfuelltAm: "", vonId: null, gemeldetVonId: null }));
100	}
