105	/** Signing-Punkte mit automatischen KYC-Werten */
106	export function signingStand(c, { kycKaeufer = false, kycVerkaeufer = false } = {}) {
107	  return SIGNING_PUNKTE.map((p) => {
108	    const s = (c.signing?.punkte || []).find((x) => x.schluessel === p.schluessel) || {};
109	    const erledigt = p.schluessel === "kyc_kaeufer" ? !!kycKaeufer : p.schluessel === "kyc_verkaeufer" ? !!kycVerkaeufer : !!s.erledigt;
110	    return { ...p, erledigt, am: s.am || "", notiz: s.notiz || "" };
111	  });
