114	/** Signing möglich? { ok, gruende[] } – KYC beider Seiten ist Pflicht (Geldwäscheprävention), unabhängig vom Gating-Schalter */
115	export function signingPruefen(c, kyc = {}) {
116	  const gruende = [];
117	  if (c.status !== "vorbereitung") gruende.push("Signing ist nur in der Vorbereitung möglich.");
118	  if (!kyc.kycKaeufer) gruende.push("KYC/KYB des Käufers ist nicht verifiziert.");
119	  if (!kyc.kycVerkaeufer) gruende.push("KYC/KYB des Verkäufers ist nicht verifiziert.");
120	  for (const p of signingStand(c, kyc)) if (!p.auto && !p.erledigt) gruende.push(`Offen: ${p.label}.`);
121	  if (!(Number(c.kaufpreis) > 0)) gruende.push("Kaufpreis fehlt.");
122	  return { ok: gruende.length === 0, gruende };
123	}
