125	/** Closing möglich? { ok, gruende[] } */
126	export function closingPruefen(c, kyc = {}) {
127	  const gruende = [];
128	  if (c.status !== "signing") gruende.push(c.status === "vorbereitung" ? "Zuerst Signing bestätigen." : "Closing ist in diesem Status nicht möglich.");
129	  if (!kyc.kycKaeufer) gruende.push("KYC/KYB des Käufers ist nicht (mehr) verifiziert.");
130	  if (!kyc.kycVerkaeufer) gruende.push("KYC/KYB des Verkäufers ist nicht (mehr) verifiziert.");
131	  const offen = (c.cps || []).filter((x) => !["erfuellt", "verzichtet"].includes(x.status));
132	  if (offen.length) gruende.push(`${offen.length} Closing Condition(s) offen: ${offen.slice(0, 3).map((x) => x.label).join("; ")}${offen.length > 3 ? " …" : ""}.`);
133	  if (!c.zahlung?.eingangAm) gruende.push(c.zahlung?.treuhand ? "Eingang des Kaufpreises auf dem Treuhand-/Notaranderkonto ist nicht bestätigt." : "Zahlungseingang des Kaufpreises ist nicht bestätigt.");
134	  if (!c.notar?.termin && c.struktur === "share") gruende.push("Notartermin für die Anteilsübertragung fehlt.");
135	  return { ok: gruende.length === 0, gruende };
136	}
