138	/** Kaufpreis aus Zuschlag (Gebot) bzw. LOI ableiten */
139	export function kaufpreisAbleiten({ gebotGesamt = null, loi = null, mwp = 0 } = {}) {
140	  if (Number(gebotGesamt) > 0) return { betrag: Math.round(Number(gebotGesamt)), quelle: "zuschlag" };
141	  if (loi?.betrag > 0) return { betrag: Math.round(loi.betrag), quelle: "loi" };
142	  if (loi?.preisProKwp > 0 && mwp > 0) return { betrag: Math.round(loi.preisProKwp * mwp * 1000), quelle: "loi" };
143	  return { betrag: 0, quelle: "" };
144	}
