181	/** Neue Schrittliste für eine Akte. `ohnePfandrecht` markiert den Rang-Schritt als „entfällt“. */
182	export function schritteAnlegen(land, { ohnePfandrecht = false } = {}) {
183	  return schritteFuer(land).map((d, i) => ({
184	    schluessel: d.schluessel, reihenfolge: i + 1, status: d.schluessel === "rang" && ohnePfandrecht ? "entfaellt" : "offen",
185	    datum: "", frist: "", notiz: d.schluessel === "rang" && ohnePfandrecht ? "Keine Grundpfandrechte angegeben." : "", nachweisWert: "", dokumentId: null, signaturId: null, vonId: null, geaendertAm: null,
186	  }));
187	}
