198	/**
199	 * Prüft einen Statuswechsel eines Schritts. Wirft GrundbuchFehler (422 Pflichtangabe, 409 Reihenfolge).
200	 * akte: { land, schritte[] }; aenderung: { schluessel, status, datum?, nachweisWert?, dokumentId?, notiz? }
201	 * Liefert den neuen Schritt (ohne Seiteneffekte).
202	 */
203	export function schrittPruefen(akte, aenderung, { heute = new Date().toISOString().slice(0, 10) } = {}) {
204	  const defs = schritteFuer(akte.land);
205	  const def = defs.find((d) => d.schluessel === aenderung.schluessel);
206	  if (!def) throw new GrundbuchFehler("Unbekannter Schritt.");
207	  const alt = (akte.schritte || []).find((s) => s.schluessel === def.schluessel);
208	  if (!alt) throw new GrundbuchFehler("Schritt fehlt in der Akte.");
209	  const status = GB_SCHRITT_STATUS[aenderung.status] ? aenderung.status : alt.status;
210	  if (status === "entfaellt" && !def.optional) throw new GrundbuchFehler(`„${def.label}“ ist Pflicht und kann nicht entfallen.`);
211	  if (status === "erledigt" || status === "in_arbeit") {
212	    const fehlt = def.nach.map((k) => (akte.schritte || []).find((s) => s.schluessel === k)).filter((s) => s && !fertig(s));
213	    if (status === "erledigt" && fehlt.length) {
214	      const labels = fehlt.map((s) => defs.find((d) => d.schluessel === s.schluessel)?.label || s.schluessel);
215	      throw new GrundbuchFehler(`Zuerst erledigen: ${labels.join(", ")}.`, 409);
216	    }
217	  }
218	  const datum = /^20\d\d-\d\d-\d\d$/.test(String(aenderung.datum || "")) ? aenderung.datum : status === "erledigt" ? alt.datum || heute : alt.datum || "";
219	  if (status === "erledigt" && datum > heute) throw new GrundbuchFehler("Das Datum der Erledigung darf nicht in der Zukunft liegen.");
220	  const nachweisWert = aenderung.nachweisWert !== undefined ? String(aenderung.nachweisWert || "").trim().slice(0, 120) : alt.nachweisWert || "";
221	  const dokumentId = aenderung.dokumentId !== undefined ? aenderung.dokumentId || null : alt.dokumentId || null;
222	  if (status === "erledigt" && def.nachweis) {
223	    const hatWert = nachweisWert.length >= 3;
224	    const ok = def.nachweis === "wert" ? hatWert : def.nachweis === "dok" ? !!dokumentId : hatWert || !!dokumentId;
225	    if (!ok) throw new GrundbuchFehler(`Bitte Nachweis angeben: ${def.nachweisLabel}.`);
226	  }
227	  return { ...alt, status, datum: status === "offen" ? "" : datum, nachweisWert, dokumentId, notiz: aenderung.notiz !== undefined ? String(aenderung.notiz || "").slice(0, 500) : alt.notiz || "" };
228	}
