230	/** Rückwärts: Ein erledigter Schritt darf nicht zurückgesetzt werden, solange ein nachfolgender Schritt erledigt ist. */
231	export function zuruecksetzenErlaubt(akte, schluessel) {
232	  const defs = schritteFuer(akte.land);
233	  const nachfolger = defs.filter((d) => d.nach.includes(schluessel)).map((d) => (akte.schritte || []).find((s) => s.schluessel === d.schluessel));
234	  return !nachfolger.some((s) => s?.status === "erledigt");
235	}
