243	/** Fristen je Schritt: ab Erledigung der letzten Voraussetzung (sonst ab Anlage), manuelle Frist hat Vorrang */
244	export function fristenBerechnen(akte, { heute = new Date().toISOString().slice(0, 10) } = {}) {
245	  const defs = schritteFuer(akte.land);
246	  const start = String(akte.erstelltAm || heute).slice(0, 10);
247	  return (akte.schritte || []).map((s) => {
248	    const d = defs.find((x) => x.schluessel === s.schluessel);
249	    if (!d) return { ...s, fristBerechnet: "", ueberfaellig: false };
250	    const basis = d.nach.map((k) => (akte.schritte || []).find((x) => x.schluessel === k)).filter((x) => x?.status === "erledigt" && x.datum).map((x) => x.datum).sort().pop();
251	    const bereit = d.nach.every((k) => fertig((akte.schritte || []).find((x) => x.schluessel === k)));
252	    const fristBerechnet = s.frist || (bereit ? plusTage(basis || start, d.fristTage) : "");
253	    return { ...s, fristBerechnet, ueberfaellig: !fertig(s) && !!fristBerechnet && fristBerechnet < heute };
254	  });
255	}
