257	/** Gesamtstatus aus den Schritten (abgebrochen bleibt) */
258	export function akteStatus(akte) {
259	  if (akte.abgebrochen) return "abgebrochen";
260	  const defs = schritteFuer(akte.land);
261	  const offen = defs.map((d) => ({ d, s: (akte.schritte || []).find((x) => x.schluessel === d.schluessel) })).filter(({ s }) => !fertig(s));
262	  if (!offen.length) return "eingetragen";
263	  // Phase des ersten offenen Pflicht-Schritts in Reihenfolge (Rang läuft parallel)
264	  const erster = offen.find(({ d }) => d.schluessel !== "rang") || offen[0];
265	  if (erster.d.schluessel === "vertrag") return "vorbereitung";
266	  return erster.d.phase;
267	}
