269	/** Nächster offener Schritt (für Listen und Portal) */
270	export function naechsterSchritt(akte) {
271	  const defs = schritteFuer(akte.land);
272	  for (const d of defs) {
273	    const s = (akte.schritte || []).find((x) => x.schluessel === d.schluessel);
274	    if (!fertig(s) && d.nach.every((k) => fertig((akte.schritte || []).find((x) => x.schluessel === k)))) return { ...d, status: s?.status || "offen" };
275	  }
276	  return null;
277	}
