279	/** Fortschritt { erledigt, gesamt, quote } (entfällt zählt nicht mit) */
280	export function fortschritt(akte) {
281	  const rel = (akte.schritte || []).filter((s) => s.status !== "entfaellt");
282	  const erledigt = rel.filter((s) => s.status === "erledigt").length;
283	  return { erledigt, gesamt: rel.length, quote: rel.length ? erledigt / rel.length : 0 };
284	}
