286	/** Dienstbarkeitsstatus der Anlage (anlagen.js DIENSTBARKEIT_STATUS) aus der Akte */
287	export function anlagenDienstbarkeitStatus(akte) {
288	  const st = akteStatus(akte);
289	  if (st === "eingetragen") return "eingetragen";
290	  const antrag = (akte.schritte || []).find((s) => s.schluessel === "antrag");
291	  if (antrag?.status === "erledigt") return "beantragt";
292	  return "vorbereitung";
293	}
