297	/**
298	 * Gebühr nach Tabelle B GNotKG (§ 34 Abs. 2) – Näherung auf Basis der Tabellenstufen in der Fassung 2013.
299	 * Die Tabellen wurden durch das Kostenrechtsänderungsgesetz 2025 angehoben – daher Aufschlag KOSTEN_AUFSCHLAG_2025
300	 * als grobe Annäherung. Vor Verwendung mit einem aktuellen GNotKG-Gebührenrechner abgleichen.
301	 */
302	const STUFEN_B = [
303	  [500, 500, 15], // bis 500 € → 15 €
304	  [2000, 500, 4],
305	  [10000, 1000, 6],
306	  [25000, 3000, 8],
307	  [50000, 5000, 10],
308	  [200000, 15000, 27],
309	  [500000, 30000, 50],
310	  [5000000, 50000, 80],
311	  [10000000, 200000, 130],
312	  [20000000, 250000, 150],
313	  [60000000, 500000, 280],
314	];
315	export const KOSTEN_AUFSCHLAG_2025 = 1.08;
316	
317	export function gnotkgTabelleB(wert) {
318	  const w = Math.max(0, Number(wert) || 0);
319	  let geb = STUFEN_B[0][2];
320	  let bis = STUFEN_B[0][0];
321	  for (const [grenze, schritt, plus] of STUFEN_B.slice(1)) {
322	    if (w <= bis) break;
323	    const teil = Math.min(w, grenze) - bis;
324	    geb += Math.ceil(teil / schritt) * plus;
325	    bis = grenze;
326	  }
327	  return geb;
328	}
