332	/**
333	 * Kostenschätzung Grundbuch (Orientierung). eingaben: { land, entgeltJahr (€/Jahr für das Nutzungsrecht bzw. Jahrespacht),
334	 * laufzeitJahre, rangruecktritt (Anzahl Gläubiger), eigentuemer (Anzahl Unterschriften) }.
