345	    positionen.push(
346	      { label: "Rechtsgeschäftsgebühr Dienstbarkeit (2 % des Entgelts)", betrag: rund(wert * 0.02), quelle: "§ 33 TP 9 GebG – nur bei entgeltlicher Einräumung; Bemessung und Befreiungen im Einzelfall prüfen" },
347	      { label: "Eintragungsgebühr Grundbuch (wertabhängig)", betrag: rund(wert * 0.011), quelle: "TP 9 lit. b GGG – Satz und Bemessungsgrundlage für Dienstbarkeiten vom Parteienvertreter bestätigen lassen (hier 1,1 % angesetzt)" },
348	      { label: "Eingabengebühr Grundbuchsgesuch", betrag: 70, von: 50, bis: 90, quelle: "TP 9 lit. a GGG (elektronische Eingabe, Stand prüfen)" },
349	      { label: `Beglaubigung der Unterschrift(en) (${personen})`, betrag: 40 * personen, von: 25 * personen, bis: 80 * personen, quelle: "Notariatstarifgesetz bzw. GGG (gerichtliche Beglaubigung) – Richtwert" },
350	      { label: "Vertragserrichtung und Grundbuchsgesuch (Notar/Rechtsanwalt)", betrag: 1500, von: 800, bis: 3000, quelle: "Honorar nach Vereinbarung bzw. Tarif (NTG/RATG) – Richtwert" }
351	    );
352	    if (glaeubiger) positionen.push({ label: `Vorrangseinräumung (${glaeubiger} Gläubiger, Beglaubigung + Bearbeitung Bank)`, betrag: 250 * glaeubiger, von: 100 * glaeubiger, bis: 500 * glaeubiger, quelle: "Bankentgelt nach Konditionen + Beglaubigung – Richtwert" });
353	    const summe = positionen.reduce((s, p) => s + p.betrag, 0);
354	    return { waehrung: "EUR", geschaeftswert: wert, positionen, summe, hinweis: "Schätzung nach österreichischem Recht (GebG, GGG, NTG) – ohne Umsatzsteuer auf Honorare. Wert = Jahresentgelt × Laufzeit. Rechtsgeschäfts- und Eintragungsgebühr hängen von der konkreten Gestaltung ab (z. B. Dienstbarkeit als Teil eines Bestandvertrags). Stand " + GB_STAND + "." };
355	  }
356	  if (land === "CH") {
357	    positionen.push(
358	      { label: "Öffentliche Beurkundung (Notariat)", betrag: 1500, von: 800, bis: 3000, quelle: "Kantonale Notariatstarife – Richtwert" },
359	      { label: "Grundbuchgebühr Eintragung", betrag: 500, von: 200, bis: 1500, quelle: "Kantonale Grundbuchgebührenverordnung – Richtwert" }
360	    );
361	    if (glaeubiger) positionen.push({ label: `Rangrücktritt (${glaeubiger} Gläubiger)`, betrag: 300 * glaeubiger, von: 150 * glaeubiger, bis: 600 * glaeubiger, quelle: "Bankentgelt + Grundbuchgebühr – Richtwert" });
362	    const summe = positionen.reduce((s, p) => s + p.betrag, 0);
363	    return { waehrung: "CHF", geschaeftswert: jahr * jahre, positionen, summe, hinweis: "Kosten in der Schweiz sind kantonal sehr unterschiedlich (Promille des Werts oder Pauschalen); beim zuständigen Notariat/Grundbuchamt Offerte einholen. Stand " + GB_STAND + "." };
364	  }
365	  // DE – Geschäftswert § 52 GNotKG: auf bestimmte Zeit höchstens 20 Jahreswerte, unbestimmt 10 Jahreswerte
366	  const wert = Math.max(jahr * Math.min(jahre, 20), 5000);
367	  const b = gnotkgTabelleB(wert) * KOSTEN_AUFSCHLAG_2025;
368	  positionen.push(
369	    { label: "Notar: Entwurf und Beglaubigung der Eintragungsbewilligung (0,5 Gebühr)", betrag: rund(b * 0.5), quelle: "KV 24102/21201 GNotKG, Tabelle B – Näherung" },
370	    { label: "Notar: Vollzug, Auslagen, Grundbuchabruf (pauschal)", betrag: 80, von: 50, bis: 150, quelle: "KV 22110 ff., 32000 ff. GNotKG – Richtwert" },
371	    { label: "Grundbuchamt: Eintragung der Dienstbarkeit (1,0 Gebühr)", betrag: rund(b), quelle: "KV 14121 GNotKG, Tabelle B – Näherung" }
372	  );
373	  if (glaeubiger) {
374	    positionen.push(
375	      { label: `Grundbuchamt: Eintragung Rangänderung (${glaeubiger} × 0,5 Gebühr)`, betrag: rund(b * 0.5 * glaeubiger), quelle: "KV 14130 GNotKG, Tabelle B – Näherung" },
376	      { label: `Beglaubigung Rangrücktrittserklärung Bank (${glaeubiger})`, betrag: 50 * glaeubiger, von: 20 * glaeubiger, bis: 70 * glaeubiger, quelle: "KV 25100 GNotKG (0,2 Gebühr, mind. 20 €, höchstens 70 €) – Bankentgelte zusätzlich" }
377	    );
378	  }
379	  const summe = positionen.reduce((s, p) => s + p.betrag, 0);
380	  return { waehrung: "EUR", geschaeftswert: wert, positionen, summe, hinweis: "Näherung nach GNotKG (Tabelle B, Stufen der Fassung 2013 mit pauschalem Aufschlag für die Anpassung 2025), zzgl. Umsatzsteuer auf Notarkosten. Geschäftswert nach § 52 GNotKG (höchstens 20 Jahreswerte, mind. 5.000 € angesetzt). Stand " + GB_STAND + "." };
381	}
