5	// Transaktionsstruktur, Zahlungsstruktur, Bedingungen (Due Diligence, Gremien, Finanzierung …), Exklusivität, Gültigkeit.
6	// Reine Funktionen; Demo-Backend und Frappe (plattform/fach/loi.py) wenden dieselben Regeln an.
7	//
8	// Pflicht immer: Text (≥ 10 Zeichen) und ein Preis > 0 (Gesamtbetrag, €/kWp oder Enterprise Value).
9	// Pflicht bei strukturierter LOI (`struktur: true`, Formular im Portal): zusätzlich Transaktionsstruktur,
10	// Zahlungsstruktur, Gültigkeit (Datum in der Zukunft, höchstens 12 Monate) und mindestens eine Bedingung
11	// bzw. ausdrücklich „keine Bedingungen“.
12	
13	export const LOI_PREISBASIS = {
14	  gesamt: "Kaufpreis gesamt (€)",
15	  proKwp: "Preis je kWp (€/kWp)",
16	  ev: "Enterprise Value (€, cash-/debt-free)",
17	};
18	export const LOI_STRUKTUR = { asset: "Asset Deal", share: "Share Deal (Anteile Projektgesellschaft)", offen: "Nach Due Diligence" };
19	export const LOI_ZAHLUNG = {
20	  einmal: "Einmalzahlung bei Closing",
21	  meilensteine: "Meilensteinzahlungen (z. B. Baurecht, RTB, COD)",
22	  earnout: "Fixbetrag plus Earn-out",
23	};
24	export const LOI_BEDINGUNGEN = {
25	  dd: "Zufriedenstellende Due Diligence (technisch, rechtlich, steuerlich)",
26	  gremien: "Zustimmung der Gremien (Investment Committee, Aufsichtsrat)",
27	  finanzierung: "Finanzierungszusage der Bank",
28	  netz: "Bestätigung Netzanschluss / Übertragung der Zusage",
29	  genehmigung: "Rechtskraft bzw. Bestandskraft der Genehmigung",
30	  kartell: "Fusionskontrolle bzw. Investitionsprüfung, falls erforderlich",
31	  keine: "Keine aufschiebenden Bedingungen",
32	};
33	export const LOI_FINANZIERUNG = { ek: "Vollständig aus Eigenmitteln", fk: "Mit Projektfinanzierung (Bank)", fonds: "Aus Fonds-/Mandatsmitteln" };
34	export const LOI_MAX_MONATE = 12;
