36	const TXT = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;
37	const mehrzeilig = (v, max) => (v === undefined || v === null || typeof v === "object" ? "" : String(v).replace(TXT, "").replace(/\r\n?/g, "\n").trim().slice(0, max));
38	const text = (v, max) => mehrzeilig(v, max).replace(/\s+/g, " ");
39	function zahl(v, min, max, stellen = 2) {
40	  if (v === undefined || v === null || v === "" || typeof v === "object" || typeof v === "boolean") return null;
41	  const n = typeof v === "number" ? v : Number(String(v).replace(/\s/g, "").replace(",", "."));
42	  if (!Number.isFinite(n) || n < min || n > max) return null;
43	  return Math.round(n * 10 ** stellen) / 10 ** stellen;
44	}
45	const auswahl = (v, erlaubt, std = "") => (Object.prototype.hasOwnProperty.call(erlaubt, v) ? v : std);
46	
47	class LoiFehler extends Error {
48	  constructor(msg) {
49	    super(msg);
50	    this.status = 422;
51	  }
52	}
53	const pflicht = (b, msg) => {
54	  if (!b) throw new LoiFehler(msg);
55	};
