57	/**
58	 * LOI bereinigen und prüfen.
59	 * @param {object} l Eingabe
60	 * @param {{mwp?: number, jetzt?: string|Date}} kontext Projektleistung für die Umrechnung €/kWp ↔ Gesamt
61	 * @returns {object} gespeicherte LOI (ohne `am`)
62	 */
63	export function loiBereinigen(l = {}, { mwp = 0, jetzt } = {}) {
64	  const heute = (jetzt ? new Date(jetzt) : new Date()).toISOString().slice(0, 10);
65	  const strukturiert = l?.struktur === true || l?.struktur === "true";
66	  const t = mehrzeilig(l?.text, 3000);
67	  pflicht(t.length >= 10, "Bitte beschreiben Sie Ihre Absichtserklärung (mind. 10 Zeichen).");
68	
69	  const preisbasis = auswahl(l?.preisbasis, LOI_PREISBASIS, l?.preisProKwp ? "proKwp" : l?.enterpriseValue ? "ev" : "gesamt");
70	  const kwp = (Number(mwp) || 0) * 1000;
71	  let betrag = zahl(l?.betrag, 0, 1e10, 0);
72	  const preisProKwp = zahl(l?.preisProKwp, 0, 10000, 2);
73	  const ev = zahl(l?.enterpriseValue, 0, 1e11, 0);
74	  const nettoschulden = zahl(l?.nettoschulden, -1e10, 1e11, 0);
75	  if (preisbasis === "proKwp") {
76	    pflicht(preisProKwp > 0, "Bitte geben Sie den Preis je kWp an.");
77	    if (kwp > 0) betrag = Math.round(preisProKwp * kwp);
78	  } else if (preisbasis === "ev") {
79	    pflicht(ev > 0, "Bitte geben Sie den Enterprise Value an.");
80	    betrag = Math.round(ev - (nettoschulden || 0)); // Eigenkapitalwert = EV − Nettofinanzverbindlichkeiten
81	    pflicht(betrag > 0, "Enterprise Value abzüglich Nettofinanzverbindlichkeiten muss positiv sein (Eigenkapitalwert).");
82	  } else pflicht(betrag > 0, "Bitte geben Sie einen indikativen Kaufpreis an.");
83	
84	  const bedingungen = Array.isArray(l?.bedingungenListe) ? [...new Set(l.bedingungenListe.filter((b) => LOI_BEDINGUNGEN[b]))] : [];
85	  if (bedingungen.includes("keine")) pflicht(bedingungen.length === 1, "„Keine aufschiebenden Bedingungen“ schließt weitere Bedingungen aus.");
86	  const gueltigBis = /^20\d\d-\d\d-\d\d$/.test(String(l?.gueltigBis || "")) ? String(l.gueltigBis) : "";
87	  const exklusivitaetWochen = zahl(l?.exklusivitaetWochen, 0, 52, 0);
88	  const struktur = auswahl(l?.transaktion, LOI_STRUKTUR, "");
89	  const zahlung = auswahl(l?.zahlung, LOI_ZAHLUNG, "");
90	  const finanzierung = auswahl(l?.finanzierung, LOI_FINANZIERUNG, "");
91	
92	  if (gueltigBis) {
93	    pflicht(gueltigBis >= heute, "Die Gültigkeit der LOI muss in der Zukunft liegen.");
94	    const max = new Date(`${heute}T00:00:00Z`);
95	    max.setUTCMonth(max.getUTCMonth() + LOI_MAX_MONATE);
96	    pflicht(gueltigBis <= max.toISOString().slice(0, 10), `Die Gültigkeit darf höchstens ${LOI_MAX_MONATE} Monate betragen.`);
97	  }
98	  if (strukturiert) {
99	    pflicht(struktur, "Bitte wählen Sie die Transaktionsstruktur (Asset Deal, Share Deal oder nach Due Diligence).");
100	    pflicht(zahlung, "Bitte wählen Sie die Zahlungsstruktur.");
101	    pflicht(gueltigBis, "Bitte geben Sie an, bis wann die LOI gilt.");
102	    pflicht(bedingungen.length > 0, "Bitte wählen Sie die Bedingungen – oder ausdrücklich „keine aufschiebenden Bedingungen“.");
103	    pflicht(finanzierung, "Bitte geben Sie an, wie der Kauf finanziert wird.");
104	    if (zahlung !== "einmal") pflicht(mehrzeilig(l?.zahlungDetails, 1000).length >= 10, "Bitte beschreiben Sie Meilensteine bzw. Earn-out (mind. 10 Zeichen).");
105	  }
106	  const bedingungenText = mehrzeilig(l?.bedingungen, 2000);
107	  return {
108	    version: strukturiert ? 2 : 1,
109	    preisbasis,
110	    betrag,
111	    preisProKwp: preisbasis === "proKwp" ? preisProKwp : kwp > 0 && betrag ? Math.round((betrag / kwp) * 100) / 100 : null,
112	    enterpriseValue: preisbasis === "ev" ? ev : null,
113	    nettoschulden: preisbasis === "ev" ? nettoschulden || 0 : null,
114	    transaktion: struktur,
115	    zahlung,
116	    zahlungDetails: mehrzeilig(l?.zahlungDetails, 1000),
117	    bedingungenListe: bedingungen,
118	    bedingungen: bedingungenText || bedingungen.map((b) => LOI_BEDINGUNGEN[b]).join("; "),
119	    finanzierung,
120	    exklusivitaetWochen,
121	    gueltigBis,
122	    text: t,
123	    ansprechpartner: text(l?.ansprechpartner, 120),
124	  };
125	}
