127	/** Zeilen für die Anzeige (Investor, Backoffice, Anbieter nach Freigabe) */
128	export function loiZeilen(loi) {
129	  if (!loi) return [];
130	  const eur = (x) => (x || x === 0 ? `${Math.round(x).toLocaleString("de-DE")} €` : "");
131	  return [
132	    { label: "Preisbasis", wert: LOI_PREISBASIS[loi.preisbasis] || "" },
133	    { label: "Indikativer Kaufpreis (Eigenkapital)", wert: eur(loi.betrag) },
134	    { label: "Preis je kWp", wert: loi.preisProKwp ? `${loi.preisProKwp.toLocaleString("de-DE")} €/kWp` : "" },
135	    { label: "Enterprise Value", wert: loi.enterpriseValue ? eur(loi.enterpriseValue) : "" },
136	    { label: "Nettofinanzverbindlichkeiten", wert: loi.enterpriseValue ? eur(loi.nettoschulden) : "" },
137	    { label: "Transaktionsstruktur", wert: LOI_STRUKTUR[loi.transaktion] || "" },
138	    { label: "Zahlungsstruktur", wert: [LOI_ZAHLUNG[loi.zahlung], loi.zahlungDetails].filter(Boolean).join(" – ") },
139	    { label: "Finanzierung", wert: LOI_FINANZIERUNG[loi.finanzierung] || "" },
140	    { label: "Bedingungen", wert: loi.bedingungen || "" },
141	    { label: "Exklusivität", wert: loi.exklusivitaetWochen ? `${loi.exklusivitaetWochen} Wochen ab Annahme` : "" },
142	    { label: "Gültig bis", wert: loi.gueltigBis ? loi.gueltigBis.split("-").reverse().join(".") : "" },
143	    { label: "Inhalt", wert: loi.text || "" },
144	  ].filter((z) => z.wert);
145	}
