50	const r2 = (x) => Math.round(x * 100) / 100;
51	
52	/**
53	 * Vorbelegung aus Projekt (öffentliche Felder), vertraulichen Angaben und Datenblatt.
54	 * @returns {{modus, eingaben, quellen: {id: "Datenblatt"|"Exposé"|"Markt"}, hinweise: string[]}}
55	 */
56	export function bewertungVorbelegung(p, vertraulich = {}, datenblatt = {}, { zielRenditePct } = {}) {
57	  const db = datenblatt || {};
58	  const vt = vertraulich || {};
59	  const quellen = {};
60	  const hinweise = [];
61	  const setze = (id, wert, quelle) => {
62	    quellen[id] = quelle;
63	    return wert;
64	  };
65	  const mwp = Number(p?.mwp) || 0;
66	  const kwp = mwp * 1000;
67	  const phase = PHASEN.find((x) => x.id === p?.phase) || PHASEN[0];
68	  const bestand = phase.id === "cod";
69	  const region = regionById(regionFuerProjekt(p));
70	  const bauartId = bauartFuer(db.aufstaenderung, p?.typ);
71	  const bauart = BAUART[bauartId];
72	  const eingaben = { mwp, regionId: region.id, bauart: bauartId };
73	
74	  const preisGesamt = p?.preisModus === "gesamt" && p?.preis ? Number(p.preis) : p?.preisModus === "proKwp" && p?.preisProKwp ? Number(p.preisProKwp) * kwp : null;
75	  const ziel = zielRenditePct ?? FINANZIERUNG.diskont * 100; // Eigenkapitalrendite-Erwartung aus markt.js
76	  eingaben.zielRenditePct = setze("zielRenditePct", r2(ziel), zielRenditePct ? "Suchprofil" : "Markt");
77	  eingaben.merchantCt = setze("merchantCt", ERLOESE.merchantCt, "Markt");
78	  eingaben.opexKwp = db.opexEurKwp ? setze("opexKwp", db.opexEurKwp, "Datenblatt") : setze("opexKwp", bestand ? BESTAND.opexProKwp : FREIFLAECHE.opexProKwp, "Markt");
79	
80	  if (bestand) {
81	    const ibnJahr = db.codDatum ? Number(db.codDatum.slice(0, 4)) : new Date().getUTCFullYear() - 5;
82	    eingaben.ibnJahr = ibnJahr;
83	    eingaben.kwp = kwp;
84	    const ist = (db.ertraege || []).filter((z) => z.istMwh > 0);
85	    if (ist.length && kwp) eingaben.ertragKwhKwp = setze("ertragKwhKwp", Math.round((ist.reduce((s, z) => s + z.istMwh, 0) / ist.length / kwp) * 1000), "Datenblatt");
86	    else if (vt.ertragKwhKwp) eingaben.ertragKwhKwp = setze("ertragKwhKwp", Number(vt.ertragKwhKwp), "Exposé");
87	    else eingaben.ertragKwhKwp = setze("ertragKwhKwp", Math.round(region.ertrag * bauart.faktor * 0.97), "Markt");
88	    eingaben.verguetungCt = db.eegZuschlagCt ? setze("verguetungCt", db.eegZuschlagCt, "Datenblatt") : setze("verguetungCt", verguetungRichtwert(ibnJahr), "Markt");
89	    eingaben.modell = ibnJahr >= 2014 ? "marktpraemie" : "fest";
90	    const ha = Number(p?.flaecheHa) || mwp * bauart.haProMwp;
91	    eingaben.pachtJahr = db.pachtEurHa ? setze("pachtJahr", Math.round(db.pachtEurHa * ha), "Datenblatt") : setze("pachtJahr", Math.round(PACHT.freiflaecheProHa.mittel * ha), "Markt");
92	    eingaben.pachtEndeJahr = db.pachtEnde ? setze("pachtEndeJahr", Number(db.pachtEnde.slice(0, 4)), "Datenblatt") : setze("pachtEndeJahr", ibnJahr + 30, "Markt");
93	    eingaben.pachtVerlaengerbar = false;
94	    eingaben.wrTausch = db.wrTausch !== "erfolgt";
95	    eingaben.kaufpreis = preisGesamt ? setze("kaufpreis", Math.round(preisGesamt), "Exposé") : setze("kaufpreis", Math.round(((phase.preisProKwp.min + phase.preisProKwp.max) / 2) * kwp), "Markt");
96	    eingaben.typ = p?.typ === "dach" ? "dach" : "freiflaeche";
97	    if (!ist.length) hinweise.push("Keine Ist-Erträge im Datenblatt – Bewertung mit Gutachten- bzw. Regionswert.");
98	    return { modus: "bestand", eingaben, quellen, hinweise };
99	  }
100	
101	  // Entwicklungsprojekt
102	  eingaben.kaufpreisKwp = preisGesamt && kwp ? setze("kaufpreisKwp", r2(preisGesamt / kwp), "Exposé") : setze("kaufpreisKwp", Math.round((phase.preisProKwp.min + phase.preisProKwp.max) / 2), "Markt");
103	  if (!preisGesamt) hinweise.push("Kaufpreis „auf Anfrage“ – vorbelegt mit der Mitte der Marktspanne der Phase.");
104	  eingaben.restentwicklungKwp = setze("restentwicklungKwp", REST_ENTWICKLUNG[phase.id] ?? 0, "Markt");
105	  eingaben.capexKwp = db.capexEurKwp ? setze("capexKwp", db.capexEurKwp, "Datenblatt") : setze("capexKwp", FREIFLAECHE.capexProKwp.mittel, "Markt");
106	  eingaben.netzKm = vt.entfernungNetzKm !== undefined && vt.entfernungNetzKm !== "" && vt.entfernungNetzKm !== null ? setze("netzKm", Number(vt.entfernungNetzKm), "Exposé") : setze("netzKm", 1, "Markt");
107	  const p50 = Number(vt.ertragKwhKwp) || null;
108	  eingaben.p50 = p50 ? setze("p50", p50, "Exposé") : setze("p50", Math.round(region.ertrag * bauart.faktor), "Markt");
109	  eingaben.p90 = db.ertragP90 ? setze("p90", db.ertragP90, "Datenblatt") : setze("p90", Math.round(eingaben.p50 * 0.92), "Markt");
110	  if (!db.ertragP90) hinweise.push("Kein P90 im Datenblatt – angesetzt mit 92 % von P50 (typische 1-Jahres-Unsicherheit).");
111	  const vm = db.vermarktung;
112	  if ((vm === "eeg" || vm === "eag") && db.eegZuschlagCt) {
113	    eingaben.modell = setze("modell", "eeg", "Datenblatt");
114	    eingaben.preisCt = setze("preisCt", db.eegZuschlagCt, "Datenblatt");
115	    eingaben.vertragJahre = setze("vertragJahre", 20, "Markt");
116	  } else if (vm === "ppa" && db.ppaPreisCt) {
117	    eingaben.modell = setze("modell", "ppa", "Datenblatt");
118	    eingaben.preisCt = setze("preisCt", db.ppaPreisCt, "Datenblatt");
119	    eingaben.vertragJahre = db.ppaLaufzeitJahre ? setze("vertragJahre", db.ppaLaufzeitJahre, "Datenblatt") : setze("vertragJahre", 10, "Markt");
120	  } else if (vm === "merchant") {
121	    eingaben.modell = setze("modell", "merchant", "Datenblatt");
