142	/** Eingaben begrenzen (Server: gespeicherte Szenarien; Client: Formular) */
143	export function bewertungBereinigen(e = {}) {
144	  const out = {};
145	  for (const f of BEWERTUNG_FELDER) {
146	    const v = e[f.id];
147	    if (f.typ === "auswahl") {
148	      if (f.optionen.some(([id]) => id === v)) out[f.id] = v;
149	      continue;
150	    }
151	    const n = typeof v === "number" ? v : Number(String(v ?? "").replace(",", "."));
152	    if (v !== "" && v !== null && v !== undefined && Number.isFinite(n)) out[f.id] = Math.min(f.max, Math.max(f.min, n));
153	  }
154	  for (const k of ["mwp", "kwp", "ibnJahr"]) if (Number.isFinite(Number(e[k]))) out[k] = Number(e[k]);
155	  for (const k of ["regionId", "bauart", "typ"]) if (typeof e[k] === "string" && /^[a-zA-Z-]{2,20}$/.test(e[k])) out[k] = e[k];
156	  if (e.modus === "bestand" || e.modus === "entwicklung") out.modus = e.modus;
157	  return out;
