182	/** Bankpraxis: Darlehen auf P90 bemessen (Mindest-DSCR), Eigenkapitalrendite im P50-Fall mit diesem Darlehen */
183	function entwicklungPaar(e) {
184	  const r90 = entwicklungRechnen(e, e.p90);
