189	/**
190	 * Rechnen. Entwicklung: P50/P90, max. Kaufpreis für Ziel-EK-IRR (P50). Bestand: Wert zum Ziel-Diskont, IRR zum Kaufpreis.
191	 */
192	export function bewertungRechnen(modus, eingaben) {
193	  const e = { ...eingaben };
194	  const ziel = (e.zielRenditePct ?? 7.5) / 100;
195	  if (modus === "bestand") {
196	    const r = rechneBestand({ ...e, diskont: ziel, merchantCt: e.merchantCt, opexKwp: e.opexKwp });
197	    return {
198	      modus,
199	      wert: Math.round(r.wert),
200	      wertProKwp: Math.round(r.wertProKwp),
201	      spanne: { min: Math.round(r.spanne.min), max: Math.round(r.spanne.max) },
202	      kaufIrr: r.kaufIrr,
203	      restJahre: r.restJahre,
204	      foerderRest: r.foerderRest,
205	      performance: r.performance,
206	      einordnung: r.einordnung,
207	      cfJahr1: Math.round(r.cfJahr1),
208	      maxKaufpreis: Math.round(r.wert),
209	    };
210	  }
211	  const { r50: p50, r90: p90 } = entwicklungPaar(e);
212	  // Max. Kaufpreis (€/kWp), bei dem der EK-IRR im P50-Fall (Darlehen nach P90) das Ziel erreicht
213	  let maxKwp = null;
214	  const irrBei = (preis) => entwicklungPaar({ ...e, kaufpreisKwp: preis }).r50.ekIrr;
215	  const lo0 = irrBei(0);
216	  if (lo0 !== null && lo0 >= ziel) {
217	    let lo = 0;
218	    let hi = 1500;
219	    if ((irrBei(hi) ?? -1) >= ziel) maxKwp = hi;
220	    else {
221	      for (let i = 0; i < 30; i++) {
222	        const mid = (lo + hi) / 2;
223	        if ((irrBei(mid) ?? -1) >= ziel) lo = mid;
224	        else hi = mid;
225	      }
226	      maxKwp = Math.floor(lo);
227	    }
228	  }
229	  const zusammen = (r) => ({
230	    projektIrr: r.projektIrr,
231	    ekIrr: r.ekIrr,
232	    dscrMin: r.dscrMin,
233	    lcoeCt: r.lcoeCt,
234	    kapitalwert: Math.round(r.kapitalwert),
235	    investition: Math.round(r.investition.summe),
236	    investProKwp: Math.round(r.investProKwp),
237	    fk: Math.round(r.fk),
238	    ek: Math.round(r.ek),
239	    fkBegrenzt: r.fkBegrenzt,
240	    ertragJahr1Mwh: Math.round(r.ertragJahr1 / 1000),
241	    amortisation: r.amortisation,
242	  });
243	  return {
244	    modus,
245	    p50: zusammen(p50),
246	    p90: zusammen(p90),
247	    maxKaufpreisKwp: maxKwp,
248	    maxKaufpreis: maxKwp !== null ? Math.round(maxKwp * e.mwp * 1000) : null,
249	    kaufpreis: Math.round((e.kaufpreisKwp || 0) * e.mwp * 1000),
250	    // Darlehen nach P90 bemessen: effektive Fremdkapitalquote und ob die Wunschquote gekürzt wurde
251	    fkQuoteEff: Math.round(p90.fkQuoteEff * 1000) / 10,
252	    fkGekuerzt: p90.fkBegrenzt,
253	  };
254	}
