2	//
3	// Seiten an ein bestehendes PDF anhängen – als INKREMENTELLES UPDATE (ISO 32000-1, 7.5.6):
4	// Die Bytes des Originals bleiben vollständig und unverändert am Anfang der Datei stehen; angehängt
5	// werden nur neue Objekte (Seiten, Schriften, Bilder), eine neue Fassung des Seitenbaums und ein
6	// neuer Querverweis-Abschnitt mit /Prev. Dadurch gilt:
7	//     signiert.subarray(0, original.length) === original   und   SHA-256(original) bleibt nachprüfbar.
8	//
9	// Unterstützt klassische Querverweistabellen und Querverweis-Ströme (PDF 1.5+, Objekt-Ströme werden
10	// zum Lesen des Katalogs/Seitenbaums entpackt). Verschlüsselte PDFs werden abgelehnt.
11	// Die anzuhängenden Seiten kommen aus dem eigenen Erzeuger (server/pdf.js → PdfDokument.alsBuffer()).
12	//
13	// Nur serverseitig (Buffer, node:zlib).
14	
15	import { inflateSync } from "node:zlib";
16	
17	export class PdfAnhangFehler extends Error {}
18	
19	const L = (b) => b.toString("latin1");
