21	/** Balanciertes Dictionary ab Position i (zeigt auf "<<") → [text, endeIndex] */
22	function dictAb(s, i) {
23	  if (s.slice(i, i + 2) !== "<<") throw new PdfAnhangFehler("PDF-Struktur nicht lesbar (Dictionary).");
24	  let tiefe = 0;
25	  for (let k = i; k < s.length - 1; k++) {
26	    const c = s[k];
27	    if (c === "(") {
28	      // Stringliteral überspringen (mit Maskierung und Klammerzählung)
29	      let t = 1;
30	      k++;
31	      while (k < s.length && t > 0) {
32	        if (s[k] === "\\") k++;
33	        else if (s[k] === "(") t++;
34	        else if (s[k] === ")") t--;
35	        k++;
36	      }
37	      k--;
38	      continue;
39	    }
40	    if (c === "<" && s[k + 1] === "<") {
41	      tiefe++;
42	      k++;
43	    } else if (c === ">" && s[k + 1] === ">") {
44	      tiefe--;
45	      k++;
46	      if (tiefe === 0) return [s.slice(i, k + 1), k + 1];
47	    }
48	  }
49	  throw new PdfAnhangFehler("PDF-Struktur nicht lesbar (Dictionary offen).");
50	}
51	
52	const ref = (dict, schluessel) => {
53	  const m = new RegExp(`/${schluessel}\\s+(\\d+)\\s+(\\d+)\\s+R`).exec(dict);
54	  return m ? { nr: Number(m[1]), gen: Number(m[2]) } : null;
55	};
56	const zahlWert = (dict, schluessel) => {
57	  const m = new RegExp(`/${schluessel}\\s+(\\d+)`).exec(dict);
58	  return m ? Number(m[1]) : null;
59	};
