61	/** Beginn der Stromdaten nach dem Dictionary (Schlüsselwort "stream" + Zeilenende) */
62	function stromDaten(s, dictEnde) {
63	  let start = s.indexOf("stream", dictEnde);
64	  if (start < 0) throw new PdfAnhangFehler("PDF-Strom fehlt.");
65	  start += 6;
66	  if (s[start] === "\r") start++;
67	  if (s[start] === "\n") start++;
68	  return { start };
69	}
