71	function entpacken(roh, dict) {
72	  if (!/\/Filter\s*\/FlateDecode/.test(dict) && !/\/Filter\s*\[\s*\/FlateDecode\s*\]/.test(dict)) {
73	    if (/\/Filter/.test(dict)) throw new PdfAnhangFehler("PDF nutzt einen nicht unterstützten Kompressionsfilter.");
74	    return roh;
75	  }
76	  try {
77	    return inflateSync(roh);
78	  } catch {
79	    // manche Erzeuger hängen Zeilenenden an – bis auf Prüfsumme tolerant entpacken
80	    try {
81	      return inflateSync(roh, { finishFlush: 2 });
82	    } catch {
83	      throw new PdfAnhangFehler("PDF-Strom beschädigt.");
84	    }
85	  }
86	}
