88	/** Letzte Definition „nr gen obj“ im Klartext suchen → Text des Objekts (ohne obj/endobj) oder null */
89	function objektKlartext(s, nr) {
90	  const re = new RegExp(`(?:^|[^0-9])${nr}\\s+(\\d+)\\s+obj\\b`, "g");
91	  let m;
92	  let letzte = null;
93	  while ((m = re.exec(s))) letzte = { index: m.index + m[0].indexOf(String(nr)), laenge: m[0].length - m[0].indexOf(String(nr)), gen: Number(m[1]) };
94	  if (!letzte) return null;
95	  const start = letzte.index + letzte.laenge;
96	  const ende = s.indexOf("endobj", start);
97	  if (ende < 0) return null;
98	  return { text: s.slice(start, ende).trim(), gen: letzte.gen };
99	}
