101	/** Objekt aus Objekt-Strömen (PDF 1.5+) lesen */
102	function objektAusObjStm(buf, s, nr) {
103	  const re = /(\d+)\s+(\d+)\s+obj\s*<</g;
104	  let m;
105	  while ((m = re.exec(s))) {
106	    const dictStart = m.index + m[0].length - 2;
107	    let dict;
108	    let ende;
109	    try {
110	      [dict, ende] = dictAb(s, dictStart);
111	    } catch {
112	      continue;
113	    }
114	    if (!/\/Type\s*\/ObjStm/.test(dict)) continue;
115	    const n = zahlWert(dict, "N");
116	    const first = zahlWert(dict, "First");
117	    if (n === null || first === null) continue;
118	    const { start } = stromDaten(s, ende);
119	    let laenge = /\/Length\s+(\d+)\b(?!\s+\d+\s+R)/.exec(dict);
120	    laenge = laenge ? Number(laenge[1]) : s.indexOf("endstream", start) - start;
121	    const daten = L(entpacken(buf.subarray(start, start + laenge), dict));
122	    const kopf = daten.slice(0, first).trim().split(/\s+/).map(Number);
123	    for (let i = 0; i < n; i++) {
124	      if (kopf[i * 2] !== nr) continue;
125	      const von = first + kopf[i * 2 + 1];
126	      const bis = i + 1 < n ? first + kopf[(i + 1) * 2 + 1] : daten.length;
127	      return { text: daten.slice(von, bis).trim(), gen: 0 };
128	    }
129	  }
130	  return null;
131	}
