133	function objektLesen(buf, s, nr) {
134	  const o = objektKlartext(s, nr) || objektAusObjStm(buf, s, nr);
135	  if (!o) throw new PdfAnhangFehler(`PDF-Objekt ${nr} nicht gefunden.`);
136	  return o;
137	}
