139	/** Trailer (klassisch oder Querverweis-Strom) des letzten Abschnitts lesen */
140	function trailerLesen(s) {
141	  const sx = s.lastIndexOf("startxref");
142	  if (sx < 0) throw new PdfAnhangFehler("PDF ohne Querverweis (startxref).");
143	  const offset = Number(/startxref\s+(\d+)/.exec(s.slice(sx))?.[1]);
144	  if (!Number.isFinite(offset) || offset <= 0 || offset >= s.length) throw new PdfAnhangFehler("PDF-Querverweis ungültig.");
145	  const ab = s.slice(offset, offset + 40);
146	  if (/^\s*xref/.test(ab)) {
147	    const t = s.indexOf("trailer", offset);
148	    if (t < 0) throw new PdfAnhangFehler("PDF-Trailer fehlt.");
149	    const [dict] = dictAb(s, s.indexOf("<<", t));
150	    return { dict, offset, strom: false };
151	  }
152	  const m = /^\s*\d+\s+\d+\s+obj\s*/.exec(ab);
153	  if (!m) throw new PdfAnhangFehler("PDF-Querverweis nicht lesbar.");
154	  const [dict] = dictAb(s, offset + m[0].length);
155	  if (!/\/Type\s*\/XRef/.test(dict)) throw new PdfAnhangFehler("PDF-Querverweis-Strom nicht lesbar.");
156	  return { dict, offset, strom: true };
157	}
