159	/** Objekte eines selbst erzeugten PDFs (server/pdf.js) über dessen xref-Tabelle zerlegen */
160	function eigeneObjekte(pdf) {
161	  const s = L(pdf);
162	  const sx = Number(/startxref\s+(\d+)/.exec(s.slice(s.lastIndexOf("startxref")))[1]);
163	  const kopf = /xref\s+0\s+(\d+)\s+/.exec(s.slice(sx));
164	  const anzahl = Number(kopf[1]);
165	  const zeilenStart = sx + kopf[0].length;
166	  const offsets = [];
167	  for (let i = 1; i < anzahl; i++) offsets.push(Number(s.slice(zeilenStart + i * 20, zeilenStart + i * 20 + 10)));
168	  const objekte = new Map();
169	  offsets.forEach((o, i) => {
170	    const ende = i + 1 < offsets.length ? offsets[i + 1] : sx;
171	    const roh = s.slice(o, ende);
172	    const nr = i + 1;
173	    const koerper = roh.slice(roh.indexOf("obj\n") + 4, roh.lastIndexOf("\nendobj"));
174	    objekte.set(nr, koerper);
175	  });
176	  const trailer = s.slice(s.indexOf("trailer", sx));
177	  return { objekte, root: ref(trailer, "Root").nr, info: ref(trailer, "Info")?.nr };
178	}
