180	/** Verweise „n 0 R“ nur im Dictionary-Teil umnummerieren (nie in Strömen) */
181	function umnummerieren(koerper, abbildung) {
182	  const strom = koerper.indexOf("\nstream\n");
183	  const kopf = strom >= 0 ? koerper.slice(0, strom) : koerper;
184	  const rest = strom >= 0 ? koerper.slice(strom) : "";
185	  return kopf.replace(/\b(\d+) 0 R\b/g, (x, nr) => abbildung.get(Number(nr)) || x) + rest;
186	}
