188	/**
189	 * Hängt alle Seiten von `zusatz` (PDF aus PdfDokument) an `original` an.
190	 * Liefert { pdf (Buffer), seitenVorher, seitenNachher }.
191	 */
192	export function pdfSeitenAnhaengen(original, zusatz) {
193	  if (!Buffer.isBuffer(original) || original.length < 20) throw new PdfAnhangFehler("Leeres PDF.");
194	  const s = L(original);
195	  if (!s.slice(0, 1024).includes("%PDF-")) throw new PdfAnhangFehler("Keine PDF-Datei.");
196	  const trailer = trailerLesen(s);
197	  if (/\/Encrypt\b/.test(trailer.dict)) throw new PdfAnhangFehler("Verschlüsselte PDFs können nicht signiert werden. Bitte ohne Kennwortschutz hochladen.");
198	  const root = ref(trailer.dict, "Root");
199	  const groesse = zahlWert(trailer.dict, "Size");
200	  if (!root || !groesse) throw new PdfAnhangFehler("PDF-Trailer unvollständig.");
201	  const katalog = objektLesen(original, s, root.nr).text;
202	  const pagesRef = ref(katalog, "Pages");
203	  if (!pagesRef) throw new PdfAnhangFehler("PDF ohne Seitenbaum.");
204	  const pages = objektLesen(original, s, pagesRef.nr);
205	  const kids = /\/Kids\s*\[([^\]]*)\]/.exec(pages.text);
206	  const count = zahlWert(pages.text, "Count");
207	  if (!kids || count === null) throw new PdfAnhangFehler("PDF-Seitenbaum nicht lesbar.");
208	
209	  // Eigene Objekte übernehmen (ohne Katalog, Seitenbaum, Info) und ab /Size neu nummerieren
210	  const eigen = eigeneObjekte(zusatz);
211	  const eigenPages = ref(eigen.objekte.get(eigen.root), "Pages").nr;
212	  const eigenKids = [...eigen.objekte.get(eigenPages).matchAll(/(\d+) 0 R/g)].map((m) => Number(m[1]));
213	  const abbildung = new Map([[eigenPages, `${pagesRef.nr} ${pagesRef.gen} R`]]);
214	  let naechste = groesse;
215	  const uebernehmen = [...eigen.objekte.keys()].filter((nr) => ![eigen.root, eigenPages, eigen.info].includes(nr));
216	  for (const nr of uebernehmen) abbildung.set(nr, `${naechste++} 0 R`);
217	  const neueObjekte = uebernehmen.map((nr) => ({ nr: Number(abbildung.get(nr).split(" ")[0]), gen: 0, text: umnummerieren(eigen.objekte.get(nr), abbildung) }));
218	  const neueKids = eigenKids.map((k) => abbildung.get(k));
219	
220	  // Seitenbaum in neuer Fassung (gleiche Objektnummer): Kinder ergänzen, Anzahl erhöhen
221	  const pagesNeu = pages.text
222	    .replace(/\/Kids\s*\[([^\]]*)\]/, (_, innen) => `/Kids [${innen.trim()} ${neueKids.join(" ")}]`)
223	    .replace(/\/Count\s+\d+/, `/Count ${count + neueKids.length}`);
224	
225	  const teile = [];
226	  let laenge = original.length;
227	  const schreiben = (t) => {
228	    teile.push(Buffer.from(t, "latin1"));
229	    laenge += Buffer.byteLength(t, "latin1");
230	  };
231	  const eintraege = [];
232	  schreiben(s.endsWith("\n") || s.endsWith("\r") ? "" : "\n");
233	  const objektSchreiben = (nr, gen, text) => {
234	    eintraege.push({ nr, gen, offset: laenge });
235	    schreiben(`${nr} ${gen} obj\n${text}\nendobj\n`);
236	  };
237	  objektSchreiben(pagesRef.nr, pagesRef.gen, pagesNeu);
238	  for (const o of neueObjekte) objektSchreiben(o.nr, o.gen, o.text);
239	
240	  const info = ref(trailer.dict, "Info");
241	  const id = /\/ID\s*\[[^\]]*\]/.exec(trailer.dict)?.[0] || "";
242	  const zusatzTrailer = `${info ? ` /Info ${info.nr} ${info.gen} R` : ""}${id ? ` ${id}` : ""}`;
243	
244	  // Querverweise: zusammenhängende Nummernbereiche
245	  const abschnitte = (liste) => {
246	    const sortiert = [...liste].sort((a, b) => a.nr - b.nr);
247	    const out = [];
248	    for (const e of sortiert) {
249	      const letzter = out[out.length - 1];
250	      if (letzter && letzter.start + letzter.eintraege.length === e.nr) letzter.eintraege.push(e);
251	      else out.push({ start: e.nr, eintraege: [e] });
252	    }
253	    return out;
254	  };
255	
256	  if (!trailer.strom) {
257	    const xref = laenge;
258	    let t = "xref\n0 1\n0000000000 65535 f \n"; // freier Eintrag 0 (strenge Leser erwarten den Nullindex)
259	    for (const a of abschnitte(eintraege)) {
260	      t += `${a.start} ${a.eintraege.length}\n`;
261	      for (const e of a.eintraege) t += `${String(e.offset).padStart(10, "0")} ${String(e.gen).padStart(5, "0")} n \n`;
262	    }
263	    t += `trailer\n<< /Size ${naechste} /Root ${root.nr} ${root.gen} R /Prev ${trailer.offset}${zusatzTrailer} >>\nstartxref\n${xref}\n%%EOF\n`;
264	    schreiben(t);
265	  } else {
266	    // Querverweis-Strom (Typ 1 = belegt: Offset 4 Byte, Generation 2 Byte), unkomprimiert
267	    const xrefNr = naechste++;
268	    const xref = laenge;
269	    const alle = [...eintraege, { nr: xrefNr, gen: 0, offset: xref }];
270	    const bereiche = [{ start: 0, eintraege: [{ frei: true }] }, ...abschnitte(alle)];
271	    const daten = Buffer.alloc((alle.length + 1) * 7);
272	    let p = 0;
273	    for (const a of bereiche) {
274	      for (const e of a.eintraege) {
275	        daten[p] = e.frei ? 0 : 1;
276	        daten.writeUInt32BE(e.frei ? 0 : e.offset, p + 1);
277	        daten.writeUInt16BE(e.frei ? 65535 : e.gen, p + 5);
278	        p += 7;
279	      }
280	    }
281	    const index = bereiche.map((a) => `${a.start} ${a.eintraege.length}`).join(" ");
282	    schreiben(`${xrefNr} 0 obj\n<< /Type /XRef /Size ${naechste} /Root ${root.nr} ${root.gen} R /Prev ${trailer.offset}${zusatzTrailer} /Index [${index}] /W [1 4 2] /Length ${daten.length} >>\nstream\n`);
283	    teile.push(daten);
284	    laenge += daten.length;
285	    schreiben(`\nendstream\nendobj\nstartxref\n${xref}\n%%EOF\n`);
286	  }
287	  return { pdf: Buffer.concat([original, ...teile]), seitenVorher: count, seitenNachher: count + neueKids.length };
288	}
