290	/** Seitenzahl eines PDFs (für die Anzeige; 0, wenn nicht lesbar) */
291	export function pdfSeitenzahl(pdf) {
292	  try {
293	    const s = L(pdf);
294	    const t = trailerLesen(s);
295	    const root = ref(t.dict, "Root");
296	    const pages = ref(objektLesen(pdf, s, root.nr).text, "Pages");
297	    return zahlWert(objektLesen(pdf, s, pages.nr).text, "Count") || 0;
298	  } catch {
299	    return 0;
300	  }
301	}
