303	/** Prüft, dass `signiert` mit den unveränderten Bytes von `original` beginnt (inkrementelles Update) */
304	export const beginntMitOriginal = (signiert, original) =>
305	  Buffer.isBuffer(signiert) && Buffer.isBuffer(original) && signiert.length > original.length && signiert.subarray(0, original.length).equals(original);
