152	/**
153	 * Signiertes PDF = Original + Prüfseite(n). Liefert { pdf, sha256, seitenVorher, seitenNachher }.
154	 * Prüft vorab, dass das Original zur protokollierten Prüfsumme passt.
155	 */
156	export function signiertesPdf(original, vorgang, { erzeugtAm } = {}) {
157	  const hash = sha256Hex(original);
158	  if (vorgang.sha256Original && hash !== vorgang.sha256Original) {
159	    const e = new Error("Die Originaldatei stimmt nicht mehr mit der protokollierten Prüfsumme überein.");
160	    e.hashAbweichung = true;
161	    throw e;
162	  }
163	  const pruef = pruefseitePdf(vorgang, { erzeugtAm });
164	  const r = pdfSeitenAnhaengen(original, pruef);
165	  return { pdf: r.pdf, sha256: sha256Hex(r.pdf), seitenVorher: r.seitenVorher, seitenNachher: r.seitenNachher };
166	}
