168	/** Standard-Erklärung (NDA / Provisionsvereinbarung) als PDF zur Unterschrift – aus den bestehenden Texten */
169	export function standardErklaerungPdf({ titel, untertitel, absaetze = [], hinweis = "", unterzeichner = "" }) {
170	  const doc = new PdfDokument({ titel, thema: "Zur elektronischen Unterschrift" });
171	  const B = doc.breite - 2 * RAND;
172	  const s = doc.seite();
173	  s.rechteck(0, 0, doc.breite, 70, F.navy950);
174	  s.text(RAND, 42, "ÖkoInvest", { groesse: 18, fett: true, farbe: F.weiss });
175	  s.text(doc.breite - RAND, 42, "ZUR ELEKTRONISCHEN UNTERSCHRIFT", { groesse: 8, fett: true, farbe: F.ov300, ausrichtung: "rechts", zeichenabstand: 0.8 });
176	  let y = s.absatz(RAND, 118, titel, { breite: B, groesse: 19, fett: true, farbe: F.ink900, zeilenhoehe: 24 });
177	  if (untertitel) y = s.absatz(RAND, y + 22, untertitel, { breite: B, groesse: 10, farbe: F.ink500 });
178	  y += 30;
179	  absaetze.forEach((a, i) => {
180	    y = s.absatz(RAND, y, `${i + 1}. ${a}`, { breite: B, groesse: 11, farbe: F.ink700, zeilenhoehe: 16 }) + 18;
181	  });
182	  if (unterzeichner) {
183	    y += 10;
184	    s.text(RAND, y, `Erklärende Partei: ${unterzeichner}`, { groesse: 10, fett: true, farbe: F.ink900 });
185	    y += 18;
186	  }
187	  if (hinweis) s.absatz(RAND, y + 6, hinweis, { breite: B, groesse: 8.5, farbe: F.ink500, zeilenhoehe: 12 });
188	  s.linie(RAND, doc.hoehe - 48, doc.breite - RAND, doc.hoehe - 48);
189	  s.text(RAND, doc.hoehe - 34, "ÖkoInvest GmbH · Ostermiething (AT) · Unterschrift und Prüfprotokoll folgen auf der angehängten Prüfseite", { groesse: 7.5, farbe: F.ink500 });
190	  return doc.alsBuffer();
191	}
