37	// ================================================================ Rechte & Ausgabe
38	
39	function rolleIm(n, s) {
40	  if (!n || !s) return null;
41	  if (boLesen(n, BEREICH)) return "backoffice";
42	  if (s.erstellerId && s.erstellerId === n.id) return "ersteller";
43	  if (s.unterzeichner.some((u) => u.kontoId === n.id)) return "unterzeichner";
44	  return null;
45	}
