47	function laden(db, n, id) {
48	  angemeldet(n);
49	  const s = db.service.signaturen.find((x) => x.id === v.kennung(id));
50	  if (!s) throw nichtGefunden("Vorgang nicht gefunden.");
51	  if (!rolleIm(n, s)) throw verboten("Dieser Signaturvorgang betrifft Ihr Konto nicht.");
52	  return s;
53	}
54	
55	/** Frist abgelaufen? (wirkt sofort in der Ausgabe, gespeichert beim nächsten Schreiben) */
56	const effektiverStatus = (s) => (s.status === "laufend" && s.frist && s.frist < heute() ? "abgelaufen" : s.status);
57	
58	function ereignis(s, { art, text, kontoId = null, ip = "", userAgent = "", sha = "" }) {
59	  s.protokoll.push({ id: neueId("SP"), am: jetzt(), art, text: v.text(text, 300), kontoId, ip: ip || "", userAgent: v.text(userAgent, 300), sha256: sha || "" });
60	}
