62	function unterzeichnerAusgabe(s, u, n, rolle) {
63	  const voll = rolle === "backoffice" || u.kontoId === n.id;
64	  const us = u.unterschrift;
65	  return {
66	    id: u.id, position: u.position, kontoId: voll ? u.kontoId : undefined, name: u.name, email: voll ? u.email : undefined,
67	    status: unterzeichnerStatus({ ...s, status: effektiverStatus(s) }, u), statusLabel: UNTERZEICHNER_STATUS[unterzeichnerStatus({ ...s, status: effektiverStatus(s) }, u)]?.label,
68	    ich: u.kontoId === n.id,
69	    unterschrift: us
70	      ? {
71	          art: us.art, name: us.name, am: us.am, sha256Dokument: us.sha256Dokument, codeBestaetigtAm: us.codeBestaetigtAm,
72	          ip: voll ? us.ip : ipMaskiert(us.ip), userAgent: voll ? us.userAgent : undefined,
73	          bild: voll && us.bildPngBase64 ? `data:image/png;base64,${us.bildPngBase64}` : undefined,
74	        }
75	      : null,
76	    abgelehnt: u.abgelehnt || null,
77	    codeGesendetAm: u.kontoId === n.id ? u.code?.gesendetAm || null : undefined,
78	    codeGueltigBis: u.kontoId === n.id && u.code && !u.code.verbraucht ? u.code.ablauf : undefined,
79	    erinnertAm: rolle === "backoffice" ? u.erinnertAm || null : undefined,
80	  };
81	}
