83	function ausgabe(db, n, s, { detail = false } = {}) {
84	  const rolle = rolleIm(n, s);
85	  const status = effektiverStatus(s);
86	  const ich = s.unterzeichner.find((u) => u.kontoId === n.id) || null;
87	  const basis = {
88	    id: s.id, titel: s.titel, art: s.art, artLabel: SIGNATUR_ARTEN[s.art]?.label || s.art, status, statusLabel: SIGNATUR_STATUS[status]?.label || status,
89	    erstelltAm: s.erstelltAm, geaendertAm: s.geaendertAm, frist: s.frist || null, abgeschlossenAm: s.abgeschlossenAm || null, reihenfolge: s.reihenfolge !== false,
90	    ersteller: s.erstellerId ? kontoKurz(db, s.erstellerId) : { id: null, name: "ÖkoInvest (automatisch)", email: "" },
91	    bezug: s.bezugArt ? { art: s.bezugArt, id: s.bezugId } : null,
92	    standard: s.standard || null,
93	    fortschritt: { unterschrieben: s.unterzeichner.filter((u) => u.status === "unterschrieben").length, gesamt: s.unterzeichner.length },
94	    unterzeichner: [...s.unterzeichner].sort((a, b) => a.position - b.position).map((u) => unterzeichnerAusgabe(s, u, n, rolle)),
95	    ichBinDran: !!ich && status === "laufend" && darfJetztUnterschreiben(s, ich),
96	    meineRolle: rolle,
97	    darfWiderrufen: status === "laufend" && (boSchreiben(n, BEREICH) || s.erstellerId === n.id),
98	    darfErinnern: status === "laufend" && boSchreiben(n, BEREICH),
99	  };
100	  if (!detail) return basis;
101	  return {
102	    ...basis,
103	    nachricht: s.nachricht || "",
104	    dokument: { name: s.dokumentName, groesse: s.groesse, seiten: s.seiten || 0, sha256: s.sha256Original },
105	    signiert: s.dateiSigniert ? { name: signiertName(s), groesse: s.groesseSigniert, sha256: s.sha256Signiert, seiten: s.seitenSigniert } : null,
106	    widerruf: s.widerruf || null,
107	    protokoll: s.protokoll.map((e) => ({
108	      id: e.id, am: e.am, art: e.art, text: e.text, name: e.kontoId ? nameVon(db, e.kontoId) : "System", sha256: e.sha256 || "",
109	      ip: rolle === "backoffice" || e.kontoId === n.id ? e.ip : ipMaskiert(e.ip), userAgent: rolle === "backoffice" || e.kontoId === n.id ? e.userAgent : undefined,
110	    })),
111	    kennzeichnung: SIGNATUR_KENNZEICHNUNG,
112	    rechtshinweis: SIGNATUR_RECHTSHINWEIS,
113	    zustimmungText: SIGNATUR_ZUSTIMMUNG,
114	  };
115	}
