119	// ================================================================ Lesen
120	
121	export async function signaturen(n, { status = "", alle = false } = {}) {
122	  angemeldet(n);
123	  const db = await lesenBereit();
124	  const bo = boLesen(n, BEREICH);
125	  return db.service.signaturen
126	    .filter((s) => (alle && bo ? true : s.erstellerId === n.id || s.unterzeichner.some((u) => u.kontoId === n.id)))
127	    .filter((s) => !status || effektiverStatus(s) === status)
128	    .sort((a, b) => String(b.geaendertAm).localeCompare(String(a.geaendertAm)))
129	    .slice(0, 300)
130	    .map((s) => ausgabe(db, n, s));
