138	// ================================================================ Anlegen
139	
140	/** PDF prüfen: Magic Bytes, Größe, nicht verschlüsselt, Seiten anhängbar (Probelauf) */
141	function pdfPruefen(daten) {
142	  if (!Buffer.isBuffer(daten) || daten.length < 20 || daten.subarray(0, 5).toString("latin1") !== "%PDF-") throw new PlattformFehler(415, "Bitte laden Sie eine PDF-Datei hoch.");
143	  if (daten.length > SIGNATUR_GRENZEN.pdfMaxBytes) throw new PlattformFehler(413, "Die PDF-Datei ist größer als 10 MB.");
144	  try {
145	    const probe = new PdfDokument({ titel: "Probe" });
146	    probe.seite();
147	    pdfSeitenAnhaengen(daten, probe.alsBuffer());
148	  } catch (e) {
149	    if (e instanceof PdfAnhangFehler) throw ungueltig(`Die PDF-Datei kann nicht signiert werden: ${e.message}`);
150	    throw ungueltig("Die PDF-Datei kann nicht verarbeitet werden. Bitte als PDF (z. B. „PDF/A“) neu exportieren.");
151	  }
152	  return pdfSeitenzahl(daten);
153	}
154	
155	function unterzeichnerAufloesen(db, liste) {
156	  v.pflicht(Array.isArray(liste) && liste.length >= 1, "Bitte wählen Sie mindestens eine unterzeichnende Person.");
157	  v.pflicht(liste.length <= SIGNATUR_GRENZEN.maxUnterzeichner, `Höchstens ${SIGNATUR_GRENZEN.maxUnterzeichner} Unterzeichner.`);
158	  const gesehen = new Set();
159	  return liste.map((x, i) => {
160	    const email = v.email(x?.email || "");
161	    const kid = v.kennung(x?.kontoId || "");
162	    const u = kid ? nutzerById(db, kid) : db.nutzer.find((k) => k.email === email);
163	    v.pflicht(u && u.aktiv, `Unterzeichner ${i + 1}: Es gibt kein aktives Portal-Konto mit dieser Angabe. Unterzeichner brauchen ein Konto (Einladung über „Nutzer“ bzw. Registrierung).`);
164	    v.pflicht(!gesehen.has(u.id), "Jede Person kann nur einmal unterschreiben.");
165	    gesehen.add(u.id);
166	    return { id: neueId("SU"), position: i + 1, kontoId: u.id, name: nameVon(db, u.id) || u.email, email: u.email, status: "offen", code: null, unterschrift: null, abgelehnt: null, erinnertAm: null };
167	  });
168	}
169	
170	function eingeladenMelden(db, s) {
171	  const offen = s.unterzeichner.filter((u) => darfJetztUnterschreiben(s, u) && !u.eingeladenAm);
172	  for (const u of offen) {
173	    u.eingeladenAm = jetzt();
174	    melden(db, u.kontoId, { art: "signatur", titel: `Zur Unterschrift: ${s.titel}`, text: `${SIGNATUR_ARTEN[s.art]?.label || "Dokument"}${s.frist ? ` · bitte bis ${s.frist.split("-").reverse().join(".")}` : ""}`, link: `/portal/signatur/${s.id}`, objektArt: "signatur", objektId: s.id });
175	  }
176	}
177	
178	function vorgangAnlegen(db, { titel, art, erstellerId, bezugArt, bezugId, nachricht, frist, reihenfolge, unterzeichner, daten, dateiname, standard = null, ip = "" }) {
179	  const seiten = pdfPruefen(daten);
180	  const datei = dateiSchreiben("SIG", "pdf", daten);
181	  const s = {
182	    id: neueId("SV"), titel, art, status: "laufend", erstellerId, bezugArt: bezugArt || null, bezugId: bezugId || null, nachricht: nachricht || "",
183	    frist, reihenfolge: reihenfolge !== false, datei, dokumentName: dateiname, groesse: daten.length, seiten, sha256Original: sha256Hex(daten),
184	    dateiSigniert: null, sha256Signiert: null, unterzeichner, protokoll: [], standard, widerruf: null, erstelltAm: jetzt(), geaendertAm: jetzt(), abgeschlossenAm: null,
185	  };
186	  ereignis(s, { art: "erstellt", text: `Vorgang angelegt (${unterzeichner.length} Unterzeichner, Reihenfolge ${s.reihenfolge ? "fest" : "beliebig"})`, kontoId: erstellerId, ip, sha: s.sha256Original });
187	  db.service.signaturen.push(s);
188	  eingeladenMelden(db, s);
189	  return s;
190	}
