192	export async function signaturAnlegen(n, daten = {}, { ip = "" } = {}) {
193	  schreibNoetig(n, BEREICH, LABEL);
194	  const titel = v.text(daten.titel, 160);
195	  v.pflicht(titel.length >= 3, "Bitte geben Sie einen Titel an (mind. 3 Zeichen).");
196	  const art = v.auswahl(daten.art, SIGNATUR_ART_IDS, "");
197	  v.pflicht(art, "Bitte wählen Sie die Dokumentart.");
198	  const fristTage = Math.min(SIGNATUR_GRENZEN.fristTageMax, Math.max(1, Number(daten.fristTage) || SIGNATUR_GRENZEN.fristTageStandard));
199	  const frist = new Date(Date.now() + fristTage * 86400e3).toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });
200	  const bezugArt = daten.bezugArt ? v.auswahl(daten.bezugArt, BEZUG_ARTEN, "") : "";
201	  // PDF als Buffer (Upload der Website) oder base64 (Frappe-Vertrag)
202	  const b64 = String(daten.pdfBase64 || "");
203	  const pdf = Buffer.isBuffer(daten.pdf) ? daten.pdf : b64.length > 20 && b64.length < SIGNATUR_GRENZEN.pdfMaxBytes * 1.4 ? Buffer.from(b64, "base64") : null;
204	  v.pflicht(pdf && pdf.length > 20, "Bitte laden Sie das Dokument als PDF hoch (höchstens 10 MB).");
205	  const dateiname = (v.text(daten.dateiname, 120).replace(/[\\/:*?"<>|]/g, "_") || "dokument.pdf").replace(/(\.pdf)?$/i, ".pdf");
206	  return aendernBereit((db) => {
207	    let bezugId = null;
208	    if (bezugArt) {
209	      const liste = { vorgang: db.vorgaenge, flaeche: db.flaechen, projekt: db.projekte, interesse: db.interessen, nutzer: db.nutzer }[bezugArt] || [];
210	      const o = liste.find((x) => x.id === v.kennung(daten.bezugId));
211	      if (!o) throw nichtGefunden("Bezug nicht gefunden.");
212	      bezugId = o.id;
213	    }
214	    const s = vorgangAnlegen(db, {
215	      titel, art, erstellerId: n.id, bezugArt, bezugId, nachricht: v.mehrzeilig(daten.nachricht, 1000), frist, reihenfolge: daten.reihenfolge !== false,
216	      unterzeichner: unterzeichnerAufloesen(db, daten.unterzeichner), daten: pdf, dateiname, ip,
217	    });
218	    protokoll(db, n, "signatur", "signatur", s.id, `Signaturvorgang „${titel}“ angelegt`, ip);
219	    return ausgabe(db, n, s, { detail: true });
220	  });
221	}
