223	// ================================================================ Code & Unterschrift
224	
225	const codeHash = (s, u, code) => sha256(`${s.id}:${u.id}:${String(code).trim()}`);
226	const emailMaskiert = (e) => String(e || "").replace(/^(.).*?(.)?@/, (_, a, b) => `${a}…${b || ""}@`);
227	
228	export async function signaturCodeAnfordern(n, id, { ip = "", userAgent = "" } = {}) {
229	  angemeldet(n);
230	  return aendernBereit((db) => {
231	    const s = laden(db, n, id);
232	    if (effektiverStatus(s) !== "laufend") throw konflikt("Dieser Vorgang kann nicht mehr unterschrieben werden.");
233	    const u = s.unterzeichner.find((x) => x.kontoId === n.id);
234	    if (!u) throw verboten("Sie sind in diesem Vorgang nicht als Unterzeichner eingetragen.");
235	    if (!darfJetztUnterschreiben(s, u)) throw konflikt("Sie sind noch nicht an der Reihe – vorher unterschreiben andere Personen.");
236	    const stunde = Date.now() - 3600e3;
237	    const anzahl = s.protokoll.filter((e) => e.art === "code" && e.kontoId === n.id && new Date(e.am).getTime() > stunde).length;
238	    if (anzahl >= 5) throw new PlattformFehler(429, "Zu viele Codes angefordert – bitte warten Sie eine Stunde.");
239	    const code = String(randomInt(0, 1_000_000)).padStart(6, "0");
240	    u.code = { hash: codeHash(s, u, code), ablauf: new Date(Date.now() + SIGNATUR_GRENZEN.codeMinuten * 60e3).toISOString(), versuche: 0, gesendetAm: jetzt(), verbraucht: false };
241	    ereignis(s, { art: "code", text: `Bestätigungscode an ${emailMaskiert(u.email)} gesendet`, kontoId: n.id, ip, userAgent });
242	    mailAblegen(db, {
243	      an: u.email, anName: u.name, nutzerId: u.kontoId, art: "signatur",
244	      betreff: `Ihr Bestätigungscode zur Unterschrift – ÖkoInvest`,
245	      text: `Ihr Bestätigungscode lautet: ${code}\n\nDer Code ist ${SIGNATUR_GRENZEN.codeMinuten} Minuten gültig und gilt nur für den Vorgang ${s.id}. Geben Sie ihn nicht weiter – ÖkoInvest fragt nie telefonisch nach diesem Code.\n\n${SIGNATUR_KENNZEICHNUNG}`,
246	      link: `/portal/signatur/${s.id}`, linkText: "Zum Dokument", hinweis: "Sie haben diese E-Mail erhalten, weil Sie im Portal eine elektronische Unterschrift begonnen haben.",
247	    });
248	    s.geaendertAm = jetzt();
249	    return { ok: true, gesendetAn: emailMaskiert(u.email), gueltigBis: u.code.ablauf };
250	  });
251	}
252	
253	function unterschriftPruefen({ art, bild, name }) {
254	  if (art === "gezeichnet") {
255	    const b64 = pngBase64AusDataUrl(bild);
256	    v.pflicht(b64, "Bitte zeichnen Sie Ihre Unterschrift in das Feld.");
257	    const puffer = Buffer.from(b64, "base64");
258	    v.pflicht(istPng(puffer) && puffer.length <= SIGNATUR_GRENZEN.bildMaxBytes, "Die gezeichnete Unterschrift ist ungültig oder zu groß.");
